const dsaMarker = '\n## DSA — Docker startup exact source admission, 2026-11-08\n\n```json\n';
const dsaSourceMarker = '\n## Docker startup address-space comparison purpose 20261108\n\n```json\n';
const dsaBegin = '          # DSA_NATIVE_CONTROLS_BEGIN\n';
const dsaEnd = '          # DSA_NATIVE_CONTROLS_END\n';
const dsaNativeBlockSha256 = '7e5a716ea7420ca51cc6bbb7f683d0aea4e2ad4548f19f18a0d468ba15a2e893';
function dsaInverseWorkflow(value) {
  assert.equal(value.split(dsaBegin).length, 2, 'one exact DSA begin boundary');
  assert.equal(value.split(dsaEnd).length, 2, 'one exact DSA end boundary');
  const begin = value.indexOf(dsaBegin), finish = value.indexOf(dsaEnd) + dsaEnd.length;
  assert.ok(finish > begin + dsaBegin.length);
  assert.equal(coSha(Buffer.from(value.slice(begin, finish))), dsaNativeBlockSha256, 'complete new case hash before projection');
  const previous = value.slice(0, begin) + value.slice(finish);
  assert.equal(Buffer.byteLength(previous), 145288);
  assert.equal(coSha(Buffer.from(previous)), 'e9b608594b5641c5a51dbe9c31f3095e01c6ecf1c499417bd8dba23885d175c7');
  assert.equal(coBlob(Buffer.from(previous)), 'b2ba003b3f80897065cb582d66e4b9c32a267c4f');
  return previous;
}
test('DSA: exact new reader inverse restores every accepted b2ba byte', () => {
  assert.equal(dsaInverseWorkflow(dsa2InverseWorkflow(workflow)), coRepoGit('cat-file','blob','b2ba003b3f80897065cb582d66e4b9c32a267c4f').toString());
});
test('DSA: projection rejects duplicate, drift, missing boundary and extra outside bytes', () => {
  const previousWorkflow = dsa2InverseWorkflow(workflow);
  const begin = previousWorkflow.indexOf(dsaBegin), finish = previousWorkflow.indexOf(dsaEnd) + dsaEnd.length;
  const block = previousWorkflow.slice(begin, finish);
  for (const value of [previousWorkflow+block, previousWorkflow.replace(dsaEnd,''), previousWorkflow.replace(dsaBegin,dsaBegin+'          # injected\n'),
    previousWorkflow+'\n# unreviewed outside bytes\n', previousWorkflow.replace(dsaBegin,'          # wrong boundary\n')]) {
    assert.throws(() => dsaInverseWorkflow(value));
  }
});
