const dsa2SourceParts = [{"path":".github/workflows/production-docker-headroom-diagnostic.yml","text":"\n\n  startup_as_contract:\n    name: Validate two daemon-free startup profiles without host access\n    if: >-\n      github.event_name == 'pull_request' ||\n      (github.event_name == 'issue_comment' &&\n      github.event.issue.number == 4637 &&\n      github.event.issue.pull_request == null &&\n      github.event.comment.body == '/production diagnose-docker-startup-as current-main' &&\n      github.event.comment.user.login == github.repository_owner &&\n      github.event.comment.author_association == 'OWNER' &&\n      github.event.comment.created_at == github.event.comment.updated_at &&\n      github.run_attempt == '1' &&\n      ((github.actor == github.repository_owner && github.triggering_actor == github.repository_owner) ||\n       github.event.comment.performed_via_github_app.id == 1144995))\n    runs-on: ubuntu-24.04\n    timeout-minutes: 5\n    permissions:\n      contents: read\n    steps:\n      - uses: actions/checkout@11d5960a326750d5838078e36cf38b85af677262\n        with:\n          ref: ${{ github.sha }}\n          fetch-depth: 0\n          persist-credentials: false\n      - name: Run all startup contracts without host access\n        shell: bash\n        run: |\n          set -Eeuo pipefail\n          python3 -I -B - <<'PY_STARTUP_CONTRACT'\n          import importlib.util, pathlib, unittest\n          path = pathlib.Path('scripts/test_production_stopped_runtime_headroom.py')\n          spec = importlib.util.spec_from_file_location('startup_contract', path)\n          module = importlib.util.module_from_spec(spec)\n          spec.loader.exec_module(module)\n          result = unittest.TextTestRunner(verbosity=2).run(module.startup_contract_suite())\n          raise SystemExit(not result.wasSuccessful())\n          PY_STARTUP_CONTRACT\n\n  startup_as_compare:\n    name: One fresh OWNER daemon-free startup comparison\n    needs: startup_as_contract\n    if: >-\n      github.event_name == 'issue_comment' &&\n      github.event.issue.number == 4637 &&\n      github.event.issue.pull_request == null &&\n      github.event.comment.body == '/production diagnose-docker-startup-as current-main' &&\n      github.event.comment.user.login == github.repository_owner &&\n      github.event.comment.author_association == 'OWNER' &&\n      github.event.comment.created_at == github.event.comment.updated_at &&\n      github.run_attempt == '1' &&\n      ((github.actor == github.repository_owner && github.triggering_actor == github.repository_owner) ||\n       github.event.comment.performed_via_github_app.id == 1144995) &&\n      needs.startup_as_contract.result == 'success'\n    runs-on: ubuntu-24.04\n    timeout-minutes: 5\n    concurrency:\n      group: pc-crop-registration-lifecycle\n      cancel-in-progress: false\n      queue: max\n    permissions:\n      contents: read\n      issues: read\n    env:\n      SSH_HOST_SECRET: ${{ secrets.PC_PROD_HOST }}\n      SSH_USER_SECRET: ${{ secrets.PC_PROD_SSH_USER }}\n      SSH_PORT_SECRET: ${{ secrets.PC_PROD_SSH_PORT }}\n      SSH_KEY_PRIMARY: ${{ secrets.PC_PROD_SSH_KEY }}\n      SSH_KEY_SECONDARY: ${{ secrets.PC_PROD_SSH_PRIVATE_KEY }}\n      SSH_KEY_FALLBACK: ${{ secrets.VPS_SSH_KEY }}\n      SSH_HOST_FINGERPRINT_SECRET: ${{ secrets.PC_PROD_SSH_HOST_FINGERPRINT }}\n    steps:\n      - uses: actions/checkout@11d5960a326750d5838078e36cf38b85af677262\n        with:\n          ref: ${{ github.sha }}\n          fetch-depth: 0\n          persist-credentials: false\n      - name: Admit exact source purpose and unchanged fresh OWNER command before protected transport\n        env:\n          GH_TOKEN: ${{ github.token }}\n          TRIGGERING_ACTOR: ${{ github.triggering_actor }}\n        shell: bash\n        run: |\n          set -Eeuo pipefail\n          python3 -B scripts/production_docker_startup_controller.py --admit\n      - name: Reuse unchanged pinned identity resolver with private runner evidence\n        env:\n          EVIDENCE_DIR: ${{ runner.temp }}/docker-startup-key-private\n        shell: bash\n        run: |\n          set -Eeuo pipefail\n          umask 077\n          python3 -B scripts/production_docker_startup_controller.py --key-script > \"$RUNNER_TEMP/docker-startup-key.sh\"\n          bash \"$RUNNER_TEMP/docker-startup-key.sh\"\n      - name: Revalidate fresh current main and perform the sole bounded transport\n        env:\n          GH_TOKEN: ${{ github.token }}\n          TRIGGERING_ACTOR: ${{ github.triggering_actor }}\n        shell: bash\n        run: |\n          set -Eeuo pipefail\n          python3 -B scripts/production_docker_startup_controller.py --run\n      - name: Validate and export only closed comparison fields\n        if: always()\n        shell: bash\n        run: |\n          set -Eeuo pipefail\n          if [[ -f \"$RUNNER_TEMP/docker-startup-candidate.json\" ]]; then\n            python3 -B scripts/production_docker_startup_controller.py --publish\n          fi\n      - name: Upload the closed result only\n        if: always()\n        uses: actions/upload-artifact@ea165f8d65b6e75b540449e92b4886f43607fa02\n        with:\n          name: docker-startup-address-space-${{ github.run_id }}-${{ github.run_attempt }}\n          path: artifacts/docker-startup-address-space/closed-result.json\n          if-no-files-found: ignore\n          retention-days: 7\n      - name: Remove this runner's transient protected material\n        if: always()\n        shell: bash\n        run: |\n          rm -f -- \"$HOME/.ssh/id_pc_prod\" \"$HOME/.ssh/known_hosts\" \"$RUNNER_TEMP/docker-startup-key.sh\" \"$RUNNER_TEMP/docker-startup-candidate.json\"\n          rm -f -- \"$RUNNER_TEMP/docker-startup-key-private/ssh-key-fingerprint.txt\"\n"},{"path":"scripts/test_production_stopped_runtime_headroom.py","text":"\n\ndef startup_contract_suite():\n    \"\"\"Native-only regression fixtures. The real transport and Docker are never invoked.\"\"\"\n    import ast, copy, ctypes, datetime as dt, hashlib, importlib.util, json, os\n    from pathlib import Path\n    import resource, signal, subprocess, sys, tempfile, textwrap, time, unittest\n    from types import SimpleNamespace as NS\n    from unittest.mock import patch\n\n    spec = importlib.util.spec_from_file_location('startup_controller', Path(__file__).with_name('production_docker_startup_controller.py'))\n    c = importlib.util.module_from_spec(spec)\n    spec.loader.exec_module(c)\n    SOURCES = {p:Path(p).read_bytes() for p in c.SOURCE_PATHS}\n    WORKFLOW, REMOTE, h, transport = c.sections(SOURCES)\n    accepted_queue = Path(c.QUEUE).read_text()\n    PREDECESSOR_QUEUE = ''.join(marker+c.wire(c.record_block(accepted_queue,marker,cap)[0])+'\\n```\\n'\n        for marker,cap in ((c.PURPOSE_MARKER,18999),(c.ADMISSION_MARKER,7720)))\n    REVIEW_BODY = 'SYNTHETIC LOCAL CONTRACT FIXTURE; NOT A REAL REVIEW OR EXECUTION DISPOSITION. ' * 3\n    REAL_POPEN = subprocess.Popen\n    IDENTITY = tuple((1, i+1, 0o100755, 0, 0, 123456, 7, 8) for i in range(4))\n    TARGET = 'a' * 40\n    SECRET = 'PRIVATE_FIXTURE_MUST_NEVER_BE_EXPORTED'\n\n    def record():\n        # Fixed actual reviewer identities are schema constraints, not a claim that this fixture was reviewed.\n        def review(source,identifier):\n            value={'status':'CLEAN_PRIVATE_SOURCE_ONLY','reviewerIdentity':c.SOURCE_REVIEWER if source else c.GOVERNANCE_REVIEWER,\n                'authorIdentity':c.SOURCE_AUTHOR if source else c.GOVERNANCE_AUTHOR,'independent':True,\n                'findings':{'P0':0,'P1':0,'P2':0},'artifact':{'bytes':len(REVIEW_BODY.encode()),'sha256':hashlib.sha256(REVIEW_BODY.encode()).hexdigest()},\n                'comment':{'id':identifier,'issue':5469,'publisher':'pachaninm-lab','appId':1144995,'createdAt':'2026-11-09T11:00:00Z'}}\n            if source: value['kind']='PRIVATE_SOURCE_REVIEW'\n            return value\n        prior=c.record_block(PREDECESSOR_QUEUE,c.ADMISSION_MARKER,7720)[0]\n        governance=[{**row,'blob':'f'*40,'bytes':row['bytes']+1,'sha256':'e'*64} for row in prior['governanceAfter']]\n        return {'schema':'pc.docker-startup-source-admission.v2','core':{'purposeId':c.PURPOSE,\n            'authorityBaseExactMain':c.BASE,'retainedSourceHead':c.RETAINED,'predecessor':copy.deepcopy(c.PREDECESSOR),\n            'sourceAfter':[c.pin(p,SOURCES[p]) for p in c.SOURCE_PATHS],\n            'sourcePatch':{'bytes':123456,'sha256':'a'*64},'sourceReview':review(True,'91'),'runtimeAllowance':'NOT_ISSUED_BY_SOURCE'},\n            'governanceAfter':governance,'governancePatch':{'bytes':123456,'sha256':'b'*64},'governanceReview':review(False,'92')}\n\n    def queue(value):\n        return (PREDECESSOR_QUEUE + c.MARKER + c.wire(value) + '\\n```\\n').encode()\n\n    def event_pair():\n        live = {'id':42,'issue_url':'https://api.github.com/repos/pachaninm-lab/pachanin-demo/issues/4637',\n            'body':c.COMMAND,'user':{'login':'pachaninm-lab'},'author_association':'OWNER',\n            'created_at':'2026-11-09T12:00:00Z','updated_at':'2026-11-09T12:00:00Z',\n            'performed_via_github_app':{'id':1144995}}\n        return {'action':'created','issue':{'number':4637},'comment':copy.deepcopy(live)},live\n\n    def fixture_collect(programs, identity=None, clean_override=None, command_seconds=None):\n        calls, children = [], []\n        def spawn(argv, **kw):\n            assert argv == ('/usr/bin/docker','--version')\n            assert kw['env'] == {'PATH':'/usr/sbin:/usr/bin:/sbin:/bin','LC_ALL':'C'}\n            assert kw['cwd'] == '/' and kw['stdin'] == subprocess.DEVNULL and kw['close_fds'] and kw['start_new_session']\n            index = len(calls)\n            assert index < len(programs) <= 2\n            calls.append(argv)\n            child = REAL_POPEN([sys.executable,'-I','-c',programs[index]], **kw)\n            children.append(child)\n            return child\n        kwargs = {'return_value':IDENTITY} if identity is None else {'side_effect':identity}\n        with patch.dict(h, {'trusted_identity':unittest.mock.Mock(**kwargs)}), patch.object(os,'geteuid',return_value=0), \\\n             patch.object(subprocess,'Popen',side_effect=spawn):\n            if clean_override is None and command_seconds is None:\n                result = h['collect']()\n            else:\n                original_close = h['OwnedChildLease'].close\n                def close(lease,proc,deadline):\n                    actual = original_close(lease,proc,deadline)\n                    return actual if clean_override is None else bool(actual and clean_override)\n                with patch.object(h['OwnedChildLease'],'close',close), patch.dict(h,{'COMMAND_SECONDS':command_seconds or 12}):\n                    result = h['collect']()\n        assert all(child.poll() is not None for child in children), 'FIXTURE_OWNED_CHILD_LEFT_RUNNING'\n        h['validate_report'](result)\n        return result,calls\n\n    class StartupMeasurements(unittest.TestCase):\n        def test_two_actual_children_limits_and_cleanup(self):\n            common = ('import ctypes,os,resource,signal; '\n                'assert resource.getrlimit(resource.RLIMIT_CORE)==(0,0); '\n                'assert resource.getrlimit(resource.RLIMIT_FSIZE)==(0,0); '\n                'assert all(0<=n<=2 for n in resource.getrlimit(resource.RLIMIT_CPU)); '\n                'v=ctypes.c_int(); assert ctypes.CDLL(None).prctl(2,ctypes.byref(v),0,0,0)==0; '\n                'assert v.value==signal.SIGKILL; assert os.getcwd()==\"/\"; '\n                'assert os.environ[\"LC_ALL\"]==\"C\" and \"GH_TOKEN\" not in os.environ; ')\n            inherited = resource.getrlimit(resource.RLIMIT_AS)\n            programs = [common+'assert resource.getrlimit(resource.RLIMIT_AS)=='+repr(inherited)+'; print(\"ok\")',\n                        common+'assert resource.getrlimit(resource.RLIMIT_AS)==(536870912,536870912); print(\"ok\")']\n            value,calls = fixture_collect(programs)\n            self.assertEqual(len(calls),2)\n            self.assertEqual(value['comparison'],'STARTUP_FAILURE_NOT_REPRODUCED')\n            self.assertTrue(all(r['cleanup_attestation']=='OWNED_ANCESTRY_REAPED' for r in value['measurements']))\n\n        def test_exact_go_signal_is_useful_but_not_original19_or_root_cause(self):\n            value,calls = fixture_collect(['print(\"control\")',\n                'import sys; sys.stderr.write(\"fatal error: failed to reserve page summary memory\\\\n'+SECRET+'\"); raise SystemExit(2)'])\n            self.assertEqual(len(calls),2)\n            self.assertEqual(value['comparison'],'CURRENT_STARTUP_AS_FAILURE_REPRODUCED')\n            self.assertEqual(value['root_cause'],'NOT_ESTABLISHED')\n            self.assertEqual(value['original19'],'NOT_ATTESTED')\n            raw = json.dumps(value)\n            self.assertNotIn(SECRET,raw)\n            self.assertNotIn(hashlib.sha256(SECRET.encode()).hexdigest(),raw)\n            self.assertNotIn('stderr_sha256',raw)\n            self.assertNotIn('/usr/bin',raw)\n\n        def test_unknown_nonzero_never_establishes_comparison(self):\n            value,_ = fixture_collect(['pass','import sys; sys.stderr.write(\"'+SECRET+'\"); raise SystemExit(2)'])\n            self.assertEqual(value['comparison'],'NOT_PROVEN')\n            self.assertEqual(value['status'],'UNKNOWN')\n\n        def test_failed_control_never_starts_capped_child(self):\n            value,calls = fixture_collect(['raise SystemExit(3)'])\n            self.assertEqual(len(calls),1)\n            self.assertEqual(value['measurements'][1],h['empty_row'](h['PROFILES'][1]))\n\n        def test_real_signal_is_preserved(self):\n            value,calls = fixture_collect(['import os,signal; os.kill(os.getpid(),signal.SIGTERM)'])\n            self.assertEqual(len(calls),1)\n            self.assertEqual(value['measurements'][0]['signal'],15)\n            self.assertIsNone(value['measurements'][0]['exit_code'])\n\n        def test_stdout_overflow_is_bounded_and_stops_comparison(self):\n            value,calls = fixture_collect(['import sys; sys.stdout.write(\"x\"*20000)'])\n            self.assertEqual(len(calls),1)\n            self.assertEqual(value['measurements'][0]['status'],'OUTPUT_LIMIT')\n            self.assertEqual(value['measurements'][0]['stdout_captured_bytes'],16385)\n\n        def test_stderr_overflow_never_classifies_partial_go_text(self):\n            value,_ = fixture_collect(['import sys; sys.stderr.write(\"fatal error: failed to reserve page summary memory\"+\"x\"*20000)'])\n            self.assertEqual(value['measurements'][0]['failure_signal'],'UNCLASSIFIED')\n            self.assertEqual(value['comparison'],'NOT_PROVEN')\n\n        def test_timeout_uses_real_process_and_reaps_before_any_second(self):\n            value,calls = fixture_collect(['import time; time.sleep(10)'],command_seconds=.15)\n            self.assertEqual(len(calls),1)\n            self.assertEqual(value['measurements'][0]['status'],'TIMED_OUT')\n            self.assertEqual(value['measurements'][0]['cleanup_attestation'],'OWNED_ANCESTRY_REAPED')\n\n        def test_cleanup_unknown_cannot_pass_or_spawn_second(self):\n            value,calls = fixture_collect(['pass'],clean_override=False)\n            self.assertEqual(len(calls),1)\n            self.assertEqual(value['measurements'][0]['status'],'CLEANUP_UNCONFIRMED')\n            self.assertEqual(value['comparison'],'NOT_PROVEN')\n\n        def test_identity_drift_stops_before_second(self):\n            value,calls = fixture_collect(['pass'],identity=[IDENTITY,IDENTITY[:-1]+((1,2,3,4,5,6,7,8),)])\n            self.assertEqual(len(calls),1)\n            self.assertFalse(value['identity_stable'])\n            self.assertEqual(value['comparison'],'NOT_PROVEN')\n\n        def test_noncomparable_inherited_as_spawns_nothing(self):\n            original = resource.getrlimit\n            with patch.object(resource,'getrlimit',side_effect=lambda kind:(536870912,536870912) if kind==resource.RLIMIT_AS else original(kind)):\n                value,calls = fixture_collect([])\n            self.assertEqual(calls,[])\n            self.assertEqual(value['comparison'],'NOT_COMPARABLE')\n\n        def test_failure_classifier_closed(self):\n            self.assertEqual(h['failure_signal'](b'',True),'NONE')\n            self.assertEqual(h['failure_signal'](b'fatal error: failed to reserve page summary memory',False),'UNCLASSIFIED')\n            self.assertEqual(h['failure_signal'](b'cannot allocate memory',True),'UNCLASSIFIED')\n\n        def test_report_rejects_wrong_fields_types_evidence_and_privilege(self):\n            value,_ = fixture_collect(['pass','pass'])\n            variants = []\n            for key,bad in [('extra',SECRET),('production_mutation',True),('deployment_authorized',True),\n                            ('elapsed_ms',False),('within_budget',1),('root_cause','ESTABLISHED'),('limits_comparable',False)]:\n                v=copy.deepcopy(value); v[key]=bad; variants.append(v)\n            for key,bad in [('stdout_captured_bytes',16386),('exit_code',True),('signal',65),\n                            ('cleanup_attestation','NOT_ATTESTED'),('stderr_sha256','f'*64),('profile','THIRD_2048_MIB')]:\n                v=copy.deepcopy(value); v['measurements'][1][key]=bad; variants.append(v)\n            v=copy.deepcopy(value); v['inherited_as_soft_bytes']=1; variants.append(v)\n            v=copy.deepcopy(value); v['binary_fingerprint_sha256']=None; variants.append(v)\n            for v in variants:\n                with self.subTest(v=v):\n                    with self.assertRaises((ValueError,TypeError,KeyError)): h['validate_report'](v)\n\n    class SourceAndOwner(unittest.TestCase):\n        def test_real_sections_preserve_old_transport_and_caps(self):\n            self.assertEqual(len(REMOTE.encode())<=20000,True)\n            self.assertEqual(hashlib.sha256(WORKFLOW[:477440]).hexdigest(),c.PREFIX_SHA)\n            self.assertEqual(hashlib.sha256(SOURCES[c.TEST][:62220]).hexdigest(),c.TEST_SHA)\n            self.assertEqual(h['ARGV'],('/usr/bin/docker','--version'))\n            self.assertEqual((h['COMMAND_SECONDS'],h['OUTER_SECONDS'],transport['TRANSPORT_SECONDS']),(12,15,45))\n            self.assertEqual(h['AS_BYTES'],536870912)\n            self.assertNotIn('stderr_sha256',REMOTE)\n            parsed=ast.parse(REMOTE)\n            calls=[n for n in ast.walk(parsed) if isinstance(n,ast.Call) and isinstance(n.func,ast.Attribute)\n                   and isinstance(n.func.value,ast.Name) and n.func.value.id=='subprocess' and n.func.attr=='Popen']\n            self.assertEqual(len(calls),1)\n            self.assertIsInstance(calls[0].args[0],ast.Name)\n            self.assertEqual(calls[0].args[0].id,'ARGV')\n\n        def test_valid_synthetic_purpose_has_no_execution_authority(self):\n            v=c.purpose(queue(record()),SOURCES)\n            self.assertEqual(v['core']['runtimeAllowance'],'NOT_ISSUED_BY_SOURCE')\n\n        def test_pending_missing_duplicate_old_purposes_fail(self):\n            v=record(); v['core']['sourceReview']['status']='PENDING'\n            for raw in (queue(v),b'no new purpose',queue(record())*2,\n                        queue(record()).replace(b'\"schema\":',b'\"schema\":\"duplicate\",\"schema\":',1)):\n                with self.subTest(raw=raw[:80]):\n                    with self.assertRaises((ValueError,TypeError,KeyError)): c.purpose(raw,SOURCES)\n\n        def test_wrong_scope_bounds_pins_review_and_booleans_fail(self):\n            variants=[]\n            for key,bad in [('extra',1),('purposeId','old-purpose'),('authorityBaseExactMain','b'*40),\n                            ('retainedSourceHead','b'*40),('runtimeAllowance','ISSUED')]:\n                v=record(); v['core'][key]=bad; variants.append(v)\n            v=record(); v['core']['predecessor']['admission']['bytes']=True; variants.append(v)\n            v=record(); v['core']['sourceAfter'][0]['sha256']='f'*64; variants.append(v)\n            v=record(); v['core']['sourceAfter'].append(v['core']['sourceAfter'][1]); variants.append(v)\n            v=record(); v['core']['sourceReview']['findings']['P0']=False; variants.append(v)\n            v=record(); v['core']['sourceReview']['reviewerIdentity']=c.SOURCE_AUTHOR; variants.append(v)\n            v=record(); v['core']['sourceReview']['kind']='SESSION'; variants.append(v)\n            v=record(); v['governanceReview']['reviewerIdentity']=c.GOVERNANCE_AUTHOR; variants.append(v)\n            for v in variants:\n                with self.subTest(v=v):\n                    with self.assertRaises((ValueError,TypeError,KeyError)): c.purpose(queue(v),SOURCES)\n\n        def test_missing_source_admission_fails_before_any_api_or_transport(self):\n            env={'GITHUB_REPOSITORY':'pachaninm-lab/pachanin-demo','GITHUB_EVENT_NAME':'issue_comment',\n                 'GITHUB_RUN_ATTEMPT':'1','GITHUB_REF':'refs/heads/main','GITHUB_SHA':TARGET,\n                 'GITHUB_WORKFLOW_SHA':TARGET,'GITHUB_WORKFLOW_REF':'pachaninm-lab/pachanin-demo/'+c.WORKFLOW+'@refs/heads/main'}\n            def blob(target,path,cap):\n                return SOURCES[path] if path in SOURCES else b'old queue only'\n            with patch.dict(os.environ,env),patch.object(c,'git',return_value=(TARGET+'\\n').encode()), \\\n                 patch.object(c,'accepted_blob',side_effect=blob),patch.object(c,'api') as api:\n                with self.assertRaises(ValueError): c.admit()\n                api.assert_not_called()\n\n        def test_owner_direct_and_accepted_app_and_reserved_time(self):\n            event,live=event_pair()\n            now=dt.datetime(2026,11,9,12,4,15,tzinfo=dt.timezone.utc)\n            for actor in ('pachaninm-lab','app-user'):\n                with patch.dict(os.environ,{'GITHUB_ACTOR':actor,'TRIGGERING_ACTOR':actor}):\n                    self.assertEqual(c.owner(event,live,now),'42')\n                    with self.assertRaises(ValueError): c.owner(event,live,now+dt.timedelta(seconds=1))\n\n        def test_complete_admission_live_ref_api_error_and_rerun_before_transport(self):\n            event,live=event_pair()\n            now=dt.datetime(2026,11,9,12,0,5,tzinfo=dt.timezone.utc)\n            review_live={'id':91,'issue_url':'https://api.github.com/repos/pachaninm-lab/pachanin-demo/issues/5469',\n                'user':{'login':'pachaninm-lab'},'author_association':'OWNER','performed_via_github_app':{'id':1144995},\n                'created_at':'2026-11-09T11:00:00Z','updated_at':'2026-11-09T11:00:00Z','body':REVIEW_BODY}\n            env={'GITHUB_REPOSITORY':'pachaninm-lab/pachanin-demo','GITHUB_EVENT_NAME':'issue_comment',\n                 'GITHUB_RUN_ATTEMPT':'1','GITHUB_REF':'refs/heads/main','GITHUB_SHA':TARGET,\n                 'GITHUB_WORKFLOW_SHA':TARGET,'GITHUB_WORKFLOW_REF':'pachaninm-lab/pachanin-demo/'+c.WORKFLOW+'@refs/heads/main',\n                 'GITHUB_EVENT_PATH':'fixture-event','GITHUB_ACTOR':'connector','TRIGGERING_ACTOR':'connector'}\n            def blob(target,path,cap):\n                return SOURCES[path] if path in SOURCES else queue(record())\n            for case in ('valid','wrong_main','api_error','second_comment_edited','rerun','workflow_sha','review_changed','review_missing'):\n                calls=[]\n                def api(path):\n                    calls.append(path)\n                    if case=='api_error': raise OSError('synthetic API failure')\n                    if path=='issues/comments/91':\n                        if case=='review_missing': raise OSError('synthetic review absent')\n                        result=copy.deepcopy(review_live)\n                        if case=='review_changed': result['body']+='drift'\n                        return result\n                    if path=='issues/4637': return {'state':'open','comments':10}\n                    if path=='git/ref/heads/main': return {'ref':'refs/heads/main','object':{'type':'commit','sha':'b'*40 if case=='wrong_main' else TARGET}}\n                    result=copy.deepcopy(live)\n                    if case=='second_comment_edited' and calls.count(path)==2: result['updated_at']='2026-11-09T12:00:01Z'\n                    return result\n                current={**env}\n                if case=='rerun': current['GITHUB_RUN_ATTEMPT']='2'\n                if case=='workflow_sha': current['GITHUB_WORKFLOW_SHA']='b'*40\n                execute=unittest.mock.Mock(return_value={'passed':True})\n                with patch.dict(os.environ,current),patch.object(c,'git',side_effect=lambda *args:(TARGET+'\\n').encode() if args[0]=='rev-parse' else b''), \\\n                     patch.object(c,'accepted_blob',side_effect=blob),patch.object(c,'sections',return_value=(WORKFLOW,REMOTE,h,{'execute':execute})), \\\n                     patch.object(c,'read',return_value=json.dumps(event).encode()),patch.object(c,'api',side_effect=api), \\\n                     patch.object(c.dt,'datetime',wraps=dt.datetime) as clock:\n                    clock.now.return_value=now\n                    if case=='valid':\n                        self.assertEqual(c.main('--run'),0)\n                        self.assertEqual(calls,['issues/comments/42','issues/comments/91','issues/4637','git/ref/heads/main','issues/comments/42'])\n                        execute.assert_called_once()\n                    else:\n                        with self.assertRaises((OSError,ValueError,KeyError)): c.main('--run')\n                        execute.assert_not_called()\n                        if case in ('rerun','workflow_sha'): self.assertEqual(calls,[])\n\n        def test_wrong_live_owner_issue_id_body_edit_app_and_future_rejected(self):\n            event,live=event_pair(); now=dt.datetime(2026,11,9,12,0,5,tzinfo=dt.timezone.utc)\n            variants=[]\n            for key,bad in [('id',43),('id',True),('body',c.COMMAND+'\\n'),('user',{'login':'other'}),\n                            ('issue_url','https://api.github.com/repos/pachaninm-lab/pachanin-demo/issues/3072'),\n                            ('author_association','MEMBER'),('updated_at','2026-11-09T12:00:01Z'),\n                            ('performed_via_github_app',{'id':1})]:\n                v=copy.deepcopy(live); v[key]=bad; variants.append(v)\n            with patch.dict(os.environ,{'GITHUB_ACTOR':'connector','TRIGGERING_ACTOR':'connector'}):\n                for v in variants:\n                    with self.subTest(v=v):\n                        with self.assertRaises((ValueError,TypeError,KeyError)): c.owner(event,v,now)\n                with self.assertRaises(ValueError): c.owner(event,live,now-dt.timedelta(seconds=6))\n                event['issue']['pull_request']={}\n                with self.assertRaises(ValueError): c.owner(event,live,now)\n\n        def test_run_calls_transport_once_only_after_fresh_admission(self):\n            with tempfile.TemporaryDirectory() as tmp,patch.dict(os.environ,{'GITHUB_SHA':TARGET,'RUNNER_TEMP':tmp}):\n                execute=unittest.mock.Mock(return_value={'passed':True})\n                prepared=(WORKFLOW,REMOTE,h,{'execute':execute})\n                with patch.object(c,'sections',side_effect=AssertionError('recompilation forbidden')),patch.object(c,'admit',return_value=(TARGET,prepared)):\n                    self.assertEqual(c.main('--run'),0)\n                    execute.assert_called_once_with(REMOTE,TARGET,Path(tmp)/'docker-startup-candidate.json')\n                execute.reset_mock()\n                with patch.object(c,'sections',side_effect=AssertionError('premature compilation')),patch.object(c,'admit',side_effect=ValueError('REJECT')):\n                    with self.assertRaises(ValueError): c.main('--run')\n                    execute.assert_not_called()\n\n        def test_closed_envelope_rejects_raw_private_fields_and_false_cleanup(self):\n            value={'schema':'pc.closed-docker-diagnostic-envelope.v2','target':TARGET,'transport_status':'TIMED_OUT',\n                'diagnostic':None,'passed':False,'production_mutation':False,'deployment_authorized':False,\n                'local_cleanup_attestation':'OWNED_ANCESTRY_REAPED'}\n            with tempfile.TemporaryDirectory() as tmp:\n                path=Path(tmp)/'closed.json'; path.write_text(json.dumps(value))\n                self.assertEqual(c.publish(TARGET,path,h),value)\n                for key,bad in [('raw_stderr',SECRET),('passed',True),('local_cleanup_attestation','NOT_ATTESTED'),('target','b'*40)]:\n                    v=dict(value); v[key]=bad; path.write_text(json.dumps(v))\n                    with self.assertRaises(ValueError): c.publish(TARGET,path,h)\n\n        def test_read_rejects_symlink_and_size(self):\n            with tempfile.TemporaryDirectory() as tmp:\n                p=Path(tmp)/'file'; p.write_bytes(b'1234'); link=Path(tmp)/'link'; link.symlink_to(p)\n                self.assertEqual(c.read(p,4),b'1234')\n                with self.assertRaises(ValueError): c.read(p,3)\n                with self.assertRaises(OSError): c.read(link,4)\n\n    class ActualRoutes(unittest.TestCase):\n        def test_actual_job_conditions_closed_new_command_only(self):\n            import re\n            expressions=[]\n            for name in ('startup_as_contract','startup_as_compare'):\n                block=WORKFLOW.decode().split('\\n  '+name+':\\n',1)[1].split('\\n    runs-on:',1)[0]\n                raw=re.search(r'\\n    if: >-\\n((?:      [^\\n]*\\n)+)',block+'\\n')[1]\n                source=' '.join(row.strip() for row in raw.splitlines()).replace('&&',' and ').replace('||',' or ').replace('null','None')\n                tree=ast.parse(source,mode='eval')\n                allowed=(ast.Expression,ast.BoolOp,ast.And,ast.Or,ast.Compare,ast.Eq,ast.Attribute,ast.Name,ast.Load,ast.Constant)\n                self.assertTrue(all(type(n) in allowed for n in ast.walk(tree)))\n                expressions.append(compile(tree,'<actual-startup-route>','eval'))\n            def route(event='issue_comment',issue=4637,body=c.COMMAND,author='owner',actor='owner',trigger='owner',\n                      association='OWNER',app=0,result='success',attempt='1',edited=False,pr=None):\n                github=NS(event_name=event,repository_owner='owner',actor=actor,triggering_actor=trigger,run_attempt=attempt,\n                    event=NS(issue=NS(number=issue,pull_request=pr),comment=NS(body=body,user=NS(login=author),\n                    author_association=association,performed_via_github_app=NS(id=app),created_at='same',updated_at='different' if edited else 'same')))\n                ctx={'github':github,'needs':NS(startup_as_contract=NS(result=result))}\n                return tuple(bool(eval(v,{'__builtins__':{}},ctx)) for v in expressions)\n            self.assertEqual(route(),(True,True))\n            self.assertEqual(route(actor='bot',trigger='bot',app=1144995),(True,True))\n            self.assertEqual(route(event='pull_request'),(True,False))\n            self.assertEqual(route(result='failure'),(True,False))\n            for changes in ({'body':'/production diagnose-docker current-main'},{'body':c.COMMAND+' '},\n                            {'issue':3072},{'author':'other'},{'actor':'other'},{'association':'NONE'},\n                            {'event':'push'},{'attempt':'2'},{'edited':True},{'pr':{}},{'body':c.COMMAND+'\\n'}):\n                with self.subTest(changes=changes): self.assertEqual(route(**changes),(False,False))\n\n    class PlaintextAdmission(unittest.TestCase):\n        def review_live(self):\n            return {'id':91,'issue_url':'https://api.github.com/repos/pachaninm-lab/pachanin-demo/issues/5469',\n                'user':{'login':'pachaninm-lab'},'author_association':'OWNER','performed_via_github_app':{'id':1144995},\n                'created_at':'2026-11-09T11:00:00Z','updated_at':'2026-11-09T11:00:00Z','body':REVIEW_BODY}\n\n        def test_complete_predecessors_are_authenticated_not_only_copied_hashes(self):\n            raw=queue(record())\n            for marker,cap in ((c.PURPOSE_MARKER,18999),(c.ADMISSION_MARKER,7720)):\n                prior,wire=c.record_block(PREDECESSOR_QUEUE,marker,cap)\n                prior['unauthorized_extra']=True\n                bad=raw.replace(wire,c.wire(prior).encode(),1)\n                with self.assertRaises(ValueError): c.purpose(bad,SOURCES)\n                with self.assertRaises(ValueError): c.purpose(raw.replace(marker.encode(),b'',1),SOURCES)\n                with self.assertRaises(ValueError): c.purpose(raw+(marker+c.wire(prior)+'\\n```\\n').encode(),SOURCES)\n\n        def test_noncanonical_oversize_and_duplicate_wire_fail(self):\n            v=record()\n            variants=[(PREDECESSOR_QUEUE+c.MARKER+json.dumps(v,indent=1)+'\\n```\\n').encode(),\n                queue(v).replace(b'\"schema\":\"pc.docker-startup-source-admission.v2\"',\n                    b'\"schema\":\"pc.docker-startup-source-admission.v2\",\"schema\":\"pc.docker-startup-source-admission.v2\"'),\n                queue(v)+b'x'*3145728]\n            v['core']['padding']='x'*4096; variants.append(queue(v))\n            for raw in variants:\n                with self.assertRaises(ValueError): c.purpose(raw,SOURCES)\n\n        def test_v2_record_is_closed_and_typed_including_all_pins(self):\n            variants=[]\n            for key,bad in [('schema','pc.docker-startup-source-admission.v1'),('core',None),('unknown',1),\n                            ('governancePatch',None),('governanceReview',None),('governanceAfter',[])]:\n                v=record(); v[key]=bad; variants.append(v)\n            for key,bad in [('bytes',True),('bytes',0),('sha256','a'*63),('blob','A'*40),('mode','100755'),('path','unknown')]:\n                v=record(); v['core']['sourceAfter'][0][key]=bad; variants.append(v)\n            for key,bad in [('bytes',True),('bytes',0),('sha256','A'*64),('blob','f'*39),('mode','100644'),('path','unknown')]:\n                v=record(); v['governanceAfter'][2][key]=bad; variants.append(v)\n            old=c.record_block(PREDECESSOR_QUEUE,c.ADMISSION_MARKER,7720)[0]\n            v=record(); v['governanceAfter']=old['governanceAfter']; variants.append(v)\n            v=record(); v['core']['sourceAfter'].reverse(); variants.append(v)\n            v=record(); v['governanceAfter'].reverse(); variants.append(v)\n            for v in variants:\n                with self.assertRaises((ValueError,TypeError,KeyError)): c.purpose(queue(v),SOURCES)\n\n        def test_designated_real_reviewers_and_complete_receipts_required(self):\n            for which in ('source','governance'):\n                for key,bad in [('status','CLEAN'),('status','PENDING'),('independent',1),('reviewerIdentity','fixture-independent'),\n                                ('authorIdentity','old-author'),('artifact',None),('comment',None)]:\n                    v=record(); r=v['core']['sourceReview'] if which=='source' else v['governanceReview']; r[key]=bad\n                    with self.assertRaises((ValueError,TypeError,KeyError)): c.purpose(queue(v),SOURCES)\n                for key,bad in [('id',91),('id',True),('id',91.0),('id','091'),('id','0'),('id','1'*21),('id','+91'),\n                                ('issue',5469.0),('appId',1144995.0),('publisher','other'),('createdAt','2026-99-99T11:00:00Z')]:\n                    v=record(); r=v['core']['sourceReview'] if which=='source' else v['governanceReview']; r['comment'][key]=bad\n                    with self.assertRaises((ValueError,TypeError,KeyError)): c.purpose(queue(v),SOURCES)\n            v=record(); v['governanceReview']['comment']['id']='91'\n            with self.assertRaises(ValueError): c.purpose(queue(v),SOURCES)\n\n        def test_public_review_requires_exact_full_body_identity_and_provenance(self):\n            c.source_review(record(),self.review_live())\n            variants=[]\n            for key,bad in [('id',92),('id',True),('id',91.0),('id','91'),('issue_url','https://api.github.com/repos/pachaninm-lab/pachanin-demo/issues/4637'),\n                            ('user',{'login':'other'}),('author_association','MEMBER'),('performed_via_github_app',{'id':1144995.0}),\n                            ('updated_at','2026-11-09T11:00:01Z'),('created_at','2026-11-09T11:00:01Z'),\n                            ('body',REVIEW_BODY[:-1]),('body','WRAPPER'+REVIEW_BODY),('body',{'sha256':hashlib.sha256(REVIEW_BODY.encode()).hexdigest()})]:\n                v=self.review_live(); v[key]=bad; variants.append(v)\n            for v in variants:\n                with self.assertRaises((ValueError,TypeError,KeyError)): c.source_review(record(),v)\n\n        def test_public_review_utf8_bytes_and_exact_limit(self):\n            body='я'*10000\n            v=record(); v['core']['sourceReview']['artifact']={'bytes':20000,'sha256':hashlib.sha256(body.encode()).hexdigest()}\n            live=self.review_live(); live['body']=body\n            c.source_review(v,live)\n            v['core']['sourceReview']['artifact']['bytes']=len(body)\n            with self.assertRaises(ValueError): c.source_review(v,live)\n            body+='x'; live['body']=body\n            v['core']['sourceReview']['artifact']={'bytes':20001,'sha256':hashlib.sha256(body.encode()).hexdigest()}\n            with self.assertRaises(ValueError): c.source_review(v,live)\n\n        def test_source_drift_for_each_of_four_files_fails_before_compile_api_or_keys(self):\n            env={'GITHUB_REPOSITORY':'pachaninm-lab/pachanin-demo','GITHUB_EVENT_NAME':'issue_comment',\n                'GITHUB_RUN_ATTEMPT':'1','GITHUB_REF':'refs/heads/main','GITHUB_SHA':TARGET,'GITHUB_WORKFLOW_SHA':TARGET,\n                'GITHUB_WORKFLOW_REF':'pachaninm-lab/pachanin-demo/'+c.WORKFLOW+'@refs/heads/main'}\n            for bad_path in c.SOURCE_PATHS:\n                def blob(target,path,cap):\n                    if path==c.QUEUE: return queue(record())\n                    return SOURCES[path]+(b'\\n# drift\\n' if path==bad_path else b'')\n                for mode in ('--admit','--run','--key-script','--publish'):\n                    with patch.dict(os.environ,env),patch.object(c,'git',return_value=(TARGET+'\\n').encode()), \\\n                         patch.object(c,'accepted_blob',side_effect=blob),patch.object(c,'sections') as sections,patch.object(c,'api') as api:\n                        with self.assertRaises(ValueError): c.main(mode)\n                        sections.assert_not_called(); api.assert_not_called()\n\n        def test_all_committed_and_worktree_sources_and_two_distinct_ancestors_required(self):\n            calls=[]\n            def blob(target,path,cap):\n                calls.append((target,path,cap))\n                return SOURCES[path] if path in SOURCES else queue(record())\n            gitcalls=[]\n            def git(*args):\n                gitcalls.append(args)\n                return (TARGET+'\\n').encode() if args==('rev-parse','HEAD') else b''\n            with patch.object(c,'git',side_effect=git),patch.object(c,'accepted_blob',side_effect=blob):\n                sources,v=c.accepted_sources(TARGET)\n            self.assertEqual(tuple(path for _,path,_ in calls),c.SOURCE_PATHS+(c.QUEUE,))\n            self.assertEqual(gitcalls,[('rev-parse','HEAD'),('merge-base','--is-ancestor',c.BASE,TARGET),\n                ('merge-base','--is-ancestor',c.RETAINED,TARGET)])\n            self.assertEqual(sources,SOURCES)\n            for denied in (c.BASE,c.RETAINED):\n                def missing(*args):\n                    if denied in args: raise ValueError('SYNTHETIC_MISSING_ANCESTOR')\n                    return git(*args)\n                with patch.object(c,'git',side_effect=missing),patch.object(c,'accepted_blob',side_effect=blob):\n                    with self.assertRaises(ValueError): c.accepted_sources(TARGET)\n\n        def test_committed_blob_worktree_regular_mode_size_and_content_identity(self):\n            with tempfile.TemporaryDirectory() as tmp:\n                p=Path(tmp)/'source.py'; raw=b'pass\\n'; p.write_bytes(raw)\n                mode='100644'; committed=raw\n                def git(*args):\n                    blob=c.pin(str(p),committed)['blob']\n                    if args[0]=='ls-tree': return (mode+' blob '+blob+'\\t'+str(p)+'\\n').encode()\n                    if args[1]=='-s': return str(len(committed)).encode()\n                    return committed\n                with patch.object(c,'git',side_effect=git):\n                    self.assertEqual(c.accepted_blob(TARGET,str(p),5),raw)\n                    p.write_bytes(b'fail\\n')\n                    with self.assertRaises(ValueError): c.accepted_blob(TARGET,str(p),5)\n                    p.write_bytes(raw); p.chmod(0o755)\n                    with self.assertRaises(ValueError): c.accepted_blob(TARGET,str(p),5)\n                    p.chmod(0o644); mode='100755'\n                    with self.assertRaises(ValueError): c.accepted_blob(TARGET,str(p),5)\n                    mode='100644'; committed=raw+b'x'\n                    with self.assertRaises(ValueError): c.accepted_blob(TARGET,str(p),5)\n                    committed=raw; q=Path(tmp)/'real.py'; p.rename(q); p.symlink_to(q)\n                    with self.assertRaises(OSError): c.accepted_blob(TARGET,str(p),5)\n\n        def test_full_prefix_drift_rejected_before_host_compilation(self):\n            for path,position in ((c.WORKFLOW,100),(c.TEST,100)):\n                bad=dict(SOURCES); data=bytearray(bad[path]); data[position]^=1; bad[path]=bytes(data)\n                with patch('builtins.compile',side_effect=AssertionError('HOST_MUST_NOT_COMPILE')):\n                    with self.assertRaises(ValueError): c.sections(bad)\n\n        def test_workflow_provider_repair_preserves_prefix_and_new_run_bounds(self):\n            import re\n            self.assertLessEqual(len(WORKFLOW),500000)\n            self.assertEqual(hashlib.sha256(WORKFLOW[:477440]).hexdigest(),c.PREFIX_SHA)\n            tail=WORKFLOW[477440:].decode()\n            runs=re.findall(r'^        run: \\|\\n((?:(?:          [^\\n]*)?\\n)+)',tail,re.M)\n            self.assertEqual(len(runs),6)\n            self.assertTrue(all(len(textwrap.dedent(run))<=21000 for run in runs))\n            compare=tail.split('\\n  startup_as_compare:',1)[1]\n            self.assertNotIn('runner.temp',compare.split('\\n    steps:',1)[0])\n            resolver=compare.split('      - name: Reuse unchanged pinned identity resolver with private runner evidence\\n',1)[1].split('      - name:',1)[0]\n            self.assertIn('          EVIDENCE_DIR: ${{ runner.temp }}/docker-startup-key-private',resolver)\n            self.assertLess(compare.index(' --admit'),compare.index(' --key-script'))\n            self.assertLess(compare.index(' --key-script'),compare.index(' --run'))\n            self.assertIn('module.startup_contract_suite()',tail)\n            self.assertNotIn('PY_DOCKER_STARTUP_CONTROLLER',tail)\n\n        def test_api_fixed_routes_response_cap_and_redirect_refusal(self):\n            import io\n            from contextlib import contextmanager\n            @contextmanager\n            def response(raw):\n                handle=io.BytesIO(raw); handle.status=200\n                yield handle\n            opener=unittest.mock.Mock()\n            with patch.dict(os.environ,{'GH_TOKEN':'SYNTHETIC_LOCAL_FIXTURE'}), \\\n                 patch.object(c.urllib.request,'build_opener',return_value=opener):\n                opener.open.return_value=response(b'{}')\n                self.assertEqual(c.api('issues/comments/91'),{})\n                opener.open.assert_called_once()\n                request=opener.open.call_args.args[0]\n                self.assertEqual(request.full_url,'https://api.github.com/repos/pachaninm-lab/pachanin-demo/issues/comments/91')\n                self.assertEqual(opener.open.call_args.kwargs,{'timeout':10})\n                for path in ('issues/comments/091','issues/comments/0','issues/comments/91?x=1','git/ref/heads/other','https://example.test'):\n                    opener.open.reset_mock()\n                    with self.assertRaises(ValueError): c.api(path)\n                    opener.open.assert_not_called()\n                opener.open.return_value=response(b' '*65537)\n                with self.assertRaises(ValueError): c.api('issues/4637')\n            self.assertIsNone(c.NoRedirect().redirect_request(None,None,None,None,None,None))\n\n    return unittest.TestSuite(unittest.defaultTestLoader.loadTestsFromTestCase(cls) for cls in (StartupMeasurements,SourceAndOwner,ActualRoutes,PlaintextAdmission))\n"},{"path":"scripts/production_docker_startup_host.py","text":"\"\"\"Two fixed daemon-free startup measurements; no inventory or release admission.\"\"\"\nimport ctypes, hashlib, json, os, re, resource, selectors, signal, stat, subprocess, time\n\nSCHEMA = 'pc.docker-startup-address-space.v1'\nARGV = ('/usr/bin/docker', '--version')\nENV = {'PATH': '/usr/sbin:/usr/bin:/sbin:/bin', 'LC_ALL': 'C'}\nAS_BYTES = 536870912\nMAX_STREAM = 16384\nCOMMAND_SECONDS = 12\nOUTER_SECONDS = 15\nPROFILES = ('INHERITED_AS', 'EXACT_AS_512_MIB')\nROW_STATES = {'NOT_RUN', 'SUCCESS', 'NONZERO', 'TIMED_OUT', 'OUTPUT_LIMIT', 'UNKNOWN', 'CLEANUP_UNCONFIRMED'}\nCLEANUP = {'NOT_STARTED', 'OWNED_ANCESTRY_REAPED', 'NOT_ATTESTED'}\nSIGNALS = {'NONE', 'GO_PAGE_SUMMARY_RESERVATION_FAILED', 'UNCLASSIFIED'}\n\ndef require(value):\n    if not value:\n        raise ValueError('STARTUP_CLOSED_REJECTED')\n\ndef fingerprint(value):\n    return tuple(getattr(value, key) for key in ('st_dev', 'st_ino', 'st_mode', 'st_uid',\n        'st_gid', 'st_size', 'st_mtime_ns', 'st_ctime_ns'))\n\ndef trusted_identity():\n    parents = [os.lstat(p) for p in ('/', '/usr', '/usr/bin')]\n    require(all(stat.S_ISDIR(p.st_mode) and p.st_uid == 0 and not p.st_mode & 0o022 for p in parents))\n    cli = os.lstat(ARGV[0])\n    require(stat.S_ISREG(cli.st_mode) and cli.st_uid == 0 and not cli.st_mode & 0o022 and cli.st_mode & 0o111)\n    return tuple(map(fingerprint, parents + [cli]))\n\ndef failure_signal(raw, complete):\n    require(type(raw) is bytes and len(raw) <= MAX_STREAM + 1 and type(complete) is bool)\n    if not complete or len(raw) > MAX_STREAM:\n        return 'UNCLASSIFIED'\n    if b'fatal error: failed to reserve page summary memory' in raw:\n        return 'GO_PAGE_SUMMARY_RESERVATION_FAILED'\n    return 'NONE' if not raw else 'UNCLASSIFIED'\n\ndef empty_row(profile):\n    return {'profile': profile, 'status': 'NOT_RUN', 'exit_code': None, 'signal': None,\n        'elapsed_ms': 0, 'stdout_captured_bytes': 0, 'stderr_captured_bytes': 0,\n        'stdout_eof': False,\n        'stderr_eof': False, 'failure_signal': 'UNCLASSIFIED', 'cleanup_attestation': 'NOT_STARTED'}\n\ndef child_limits(parent, capped):\n    resource.setrlimit(resource.RLIMIT_CORE, (0, 0))\n    current_cpu = resource.getrlimit(resource.RLIMIT_CPU)\n    cpu = min([2] + [n for n in current_cpu if n != resource.RLIM_INFINITY])\n    resource.setrlimit(resource.RLIMIT_CPU, (cpu, cpu))\n    resource.setrlimit(resource.RLIMIT_FSIZE, (0, 0))\n    if capped:\n        resource.setrlimit(resource.RLIMIT_AS, (AS_BYTES, AS_BYTES))\n        require(resource.getrlimit(resource.RLIMIT_AS) == (AS_BYTES, AS_BYTES))\n    require(ctypes.CDLL(None, use_errno=True).prctl(1, signal.SIGKILL, 0, 0, 0) == 0 and os.getppid() == parent)\n\ndef run_profile(profile, deadline, last):\n    started = time.monotonic()\n    value = empty_row(profile)\n    work_end = min(started + COMMAND_SECONDS, deadline - (1 if last else 2))\n    if work_end <= started:\n        return value\n    proc = lease = None\n    mux = selectors.DefaultSelector()\n    streams = {'out': bytearray(), 'err': bytearray()}\n    eof = {'out': False, 'err': False}\n    parent = os.getpid()\n    try:\n        lease = OwnedChildLease()\n        proc = subprocess.Popen(ARGV, stdin=subprocess.DEVNULL, stdout=subprocess.PIPE,\n            stderr=subprocess.PIPE, env=ENV, cwd='/', close_fds=True, start_new_session=True,\n            preexec_fn=lambda: child_limits(parent, profile == PROFILES[1]))\n        for stream, name in ((proc.stdout, 'out'), (proc.stderr, 'err')):\n            os.set_blocking(stream.fileno(), False)\n            mux.register(stream, selectors.EVENT_READ, name)\n        while mux.get_map():\n            remaining = work_end - time.monotonic()\n            if remaining <= 0:\n                value['status'] = 'TIMED_OUT'\n                break\n            for key, _ in mux.select(min(remaining, .05)):\n                try:\n                    raw = os.read(key.fd, min(4096, MAX_STREAM + 1 - len(streams[key.data])))\n                except BlockingIOError:\n                    continue\n                if not raw:\n                    eof[key.data] = True\n                    mux.unregister(key.fileobj)\n                else:\n                    streams[key.data].extend(raw)\n                    if len(streams[key.data]) > MAX_STREAM:\n                        value['status'] = 'OUTPUT_LIMIT'\n                        break\n            if value['status'] == 'OUTPUT_LIMIT':\n                break\n        else:\n            code = lease.wait_without_reap(proc, work_end)\n            value.update(status='SUCCESS' if code == 0 else 'NONZERO',\n                         exit_code=code if code >= 0 else None, signal=-code if code < 0 else None)\n    except subprocess.TimeoutExpired:\n        value['status'] = 'TIMED_OUT'\n    except (OSError, ValueError, subprocess.SubprocessError):\n        value['status'] = 'UNKNOWN'\n    finally:\n        mux.close()\n        clean = lease.close(proc, min(deadline, time.monotonic() + 1)) if lease is not None else proc is None\n        value['cleanup_attestation'] = ('OWNED_ANCESTRY_REAPED' if proc is not None else 'NOT_STARTED') if clean else 'NOT_ATTESTED'\n        if not clean:\n            value['status'] = 'CLEANUP_UNCONFIRMED'\n        value.update(elapsed_ms=max(0, int((time.monotonic() - started) * 1000)),\n            stdout_captured_bytes=len(streams['out']), stderr_captured_bytes=len(streams['err']),\n            stdout_eof=eof['out'], stderr_eof=eof['err'],\n            failure_signal=failure_signal(bytes(streams['err']), eof['err']))\n    return value\n\ndef comparison(value):\n    a, b = value['measurements']\n    if not value['identity_stable'] or not value['within_budget']:\n        return 'NOT_PROVEN'\n    if any(r['cleanup_attestation'] != 'OWNED_ANCESTRY_REAPED' or not r['stdout_eof'] or\n           not r['stderr_eof'] or r['status'] not in {'SUCCESS', 'NONZERO'} for r in (a, b)):\n        return 'NOT_PROVEN'\n    if a['status'] != 'SUCCESS':\n        return 'NOT_COMPARABLE'\n    if b['status'] == 'SUCCESS':\n        return 'STARTUP_FAILURE_NOT_REPRODUCED'\n    if b['exit_code'] is not None and b['exit_code'] > 0 and b['failure_signal'] == 'GO_PAGE_SUMMARY_RESERVATION_FAILED':\n        return 'CURRENT_STARTUP_AS_FAILURE_REPRODUCED'\n    return 'NOT_PROVEN'\n\ndef collect():\n    started = time.monotonic()\n    deadline = started + OUTER_SECONDS\n    value = {'schema': SCHEMA, 'status': 'NOT_RUN', 'reason': 'UNAVAILABLE', 'elapsed_ms': 0,\n        'measurements': [empty_row(p) for p in PROFILES], 'binary_fingerprint_sha256': None,\n        'binary_bytes': None, 'identity_stable': False, 'within_budget': True,\n        'inherited_as_soft_bytes': None, 'inherited_as_hard_bytes': None, 'limits_comparable': False,\n        'comparison': 'NOT_PROVEN', 'root_cause': 'NOT_ESTABLISHED', 'original19': 'NOT_ATTESTED',\n        'production_mutation': False, 'deployment_authorized': False}\n    try:\n        require(os.geteuid() == 0)\n        before = trusted_identity()\n        value['binary_fingerprint_sha256'] = hashlib.sha256(json.dumps(before[-1], separators=(',', ':')).encode()).hexdigest()\n        value['binary_bytes'] = before[-1][5]\n        soft, hard = resource.getrlimit(resource.RLIMIT_AS)\n        value['inherited_as_soft_bytes'] = None if soft == resource.RLIM_INFINITY else soft\n        value['inherited_as_hard_bytes'] = None if hard == resource.RLIM_INFINITY else hard\n        value['limits_comparable'] = (soft == resource.RLIM_INFINITY or soft > AS_BYTES) and (hard == resource.RLIM_INFINITY or hard >= AS_BYTES)\n        if not value['limits_comparable']:\n            value.update(reason='INHERITED_AS_NOT_COMPARABLE', comparison='NOT_COMPARABLE')\n            return validate_report(value)\n        value['measurements'][0] = run_profile(PROFILES[0], deadline, False)\n        require(trusted_identity() == before)\n        if (value['measurements'][0]['status'] == 'SUCCESS' and\n                value['measurements'][0]['cleanup_attestation'] == 'OWNED_ANCESTRY_REAPED' and\n                time.monotonic() + 2 < deadline):\n            value['measurements'][1] = run_profile(PROFILES[1], deadline, True)\n        value['identity_stable'] = trusted_identity() == before\n        value['reason'] = 'MEASURED' if value['identity_stable'] else 'IDENTITY_CHANGED'\n    except (OSError, ValueError, subprocess.SubprocessError):\n        value['reason'] = 'UNAVAILABLE_OR_IDENTITY_CHANGED'\n    finally:\n        value['elapsed_ms'] = max(0, int((time.monotonic() - started) * 1000))\n        value['within_budget'] = time.monotonic() <= deadline\n    value['comparison'] = comparison(value)\n    value['status'] = 'SUCCESS' if value['comparison'] in {'CURRENT_STARTUP_AS_FAILURE_REPRODUCED', 'STARTUP_FAILURE_NOT_REPRODUCED'} else 'UNKNOWN'\n    return validate_report(value)\n\ndef validate_report(value):\n    keys = {'schema','status','reason','elapsed_ms','measurements','binary_fingerprint_sha256','binary_bytes',\n        'identity_stable','within_budget','inherited_as_soft_bytes','inherited_as_hard_bytes','limits_comparable',\n        'comparison','root_cause','original19','production_mutation','deployment_authorized'}\n    require(type(value) is dict and set(value) == keys and value['schema'] == SCHEMA)\n    require(value['status'] in {'SUCCESS','UNKNOWN','NOT_RUN'} and value['reason'] in\n        {'UNAVAILABLE','INHERITED_AS_NOT_COMPARABLE','MEASURED','IDENTITY_CHANGED','UNAVAILABLE_OR_IDENTITY_CHANGED'})\n    require(value['root_cause'] == 'NOT_ESTABLISHED' and value['original19'] == 'NOT_ATTESTED' and\n            value['production_mutation'] is False and value['deployment_authorized'] is False)\n    for k in ('identity_stable','within_budget','limits_comparable'):\n        require(type(value[k]) is bool)\n    for k in ('elapsed_ms','binary_bytes','inherited_as_soft_bytes','inherited_as_hard_bytes'):\n        require(value[k] is None and k != 'elapsed_ms' or type(value[k]) is int and 0 <= value[k] < 2**63)\n    require(value['binary_fingerprint_sha256'] is None or type(value['binary_fingerprint_sha256']) is str and re.fullmatch('[0-9a-f]{64}',value['binary_fingerprint_sha256']))\n    require((value['binary_fingerprint_sha256'] is None) == (value['binary_bytes'] is None))\n    if value['limits_comparable']:\n        require((value['inherited_as_soft_bytes'] is None or value['inherited_as_soft_bytes'] > AS_BYTES) and\n                (value['inherited_as_hard_bytes'] is None or value['inherited_as_hard_bytes'] >= AS_BYTES))\n    if value['within_budget']:\n        require(value['elapsed_ms'] <= OUTER_SECONDS * 1000)\n    require(type(value['measurements']) is list and len(value['measurements']) == 2)\n    for profile, row in zip(PROFILES,value['measurements']):\n        require(type(row) is dict and set(row) == set(empty_row(profile)) and row['profile'] == profile and row['status'] in ROW_STATES)\n        require(type(row['elapsed_ms']) is int and 0 <= row['elapsed_ms'] < 2**63)\n        for k in ('stdout_captured_bytes','stderr_captured_bytes'):\n            require(type(row[k]) is int and 0 <= row[k] <= MAX_STREAM + 1)\n        for k in ('stdout_eof','stderr_eof'):\n            require(type(row[k]) is bool)\n        require(row['cleanup_attestation'] in CLEANUP and row['failure_signal'] in SIGNALS)\n        require((row['status'] == 'CLEANUP_UNCONFIRMED') == (row['cleanup_attestation'] == 'NOT_ATTESTED'))\n        code, sig = row['exit_code'], row['signal']\n        require(code is None or type(code) is int and 0 <= code <= 255)\n        require(sig is None or type(sig) is int and 1 <= sig <= 64)\n        require(code is None or sig is None)\n        if row['status'] in {'SUCCESS','NONZERO'}:\n            require(row['cleanup_attestation'] == 'OWNED_ANCESTRY_REAPED' and row['stdout_eof'] and row['stderr_eof'])\n            require((row['status'] == 'SUCCESS') == (code == 0) and (code is not None or sig is not None))\n        if row['status'] == 'NOT_RUN':\n            require(row == empty_row(profile))\n        if row['failure_signal'] == 'GO_PAGE_SUMMARY_RESERVATION_FAILED':\n            require(row['stderr_eof'] and 0 < row['stderr_captured_bytes'] <= MAX_STREAM)\n    expected = 'NOT_COMPARABLE' if value['reason'] == 'INHERITED_AS_NOT_COMPARABLE' else comparison(value)\n    require(value['comparison'] == expected)\n    require((value['status'] == 'SUCCESS') == (expected in {'CURRENT_STARTUP_AS_FAILURE_REPRODUCED','STARTUP_FAILURE_NOT_REPRODUCED'}))\n    if value['status'] == 'SUCCESS':\n        require(value['reason'] == 'MEASURED' and value['limits_comparable'] and value['binary_fingerprint_sha256'] is not None and\n                value['binary_bytes'] > 0 and value['elapsed_ms'] >= sum(r['elapsed_ms'] for r in value['measurements']))\n    require(len(json.dumps(value, separators=(',', ':')).encode()) <= 3072)\n    return value\n\nif __name__ == '__main__':\n    try:\n        report = validate_report(collect())\n        print(json.dumps(report, sort_keys=True, separators=(',', ':')))\n        raise SystemExit(0 if report['status'] == 'SUCCESS' else 1)\n    except Exception:\n        raise SystemExit(1) from None\n"},{"path":"scripts/production_docker_startup_controller.py","text":"\"\"\"Bind accepted plaintext sources and a fresh OWNER command; grants no permission.\"\"\"\nimport ast, datetime as dt, hashlib, json, os, re, stat, subprocess, sys, textwrap\nfrom pathlib import Path\nimport urllib.request\n\nWORKFLOW = '.github/workflows/production-docker-headroom-diagnostic.yml'\nTEST = 'scripts/test_production_stopped_runtime_headroom.py'\nQUEUE = 'docs/platform-v7/execution-queue.md'\nHOST = 'scripts/production_docker_startup_host.py'\nCONTROLLER = 'scripts/production_docker_startup_controller.py'\nSOURCE_PATHS = (WORKFLOW, TEST, HOST, CONTROLLER)\nSOURCE_CAPS = (500000, 262144, 20000, 65536)\nBASE = 'a346563c821781fd4530e25cb2ac77fb0b89e7bc'\nRETAINED = 'b93f7e98f1873ffbbbf1380a59f6113b940fbbfb'\nPREFIX_BYTES = 477440\nPREFIX_SHA = '2860b9abd30a929a8e0538f5515f5ea34864d8b5e08cac8910511c296c19b22c'\nTEST_SHA = 'ba73a1b698ba48de1085574b0863cf1ae2ea8940dbed1977c34d014c537ab4b9'\nPURPOSE = 'docker-startup-plaintext-recovery-20261109'\nCOMMAND = '/production diagnose-docker-startup-as current-main'\nMARKER = '\\n## DSA2 — Docker startup plaintext recovery, 2026-11-09\\n\\n```json\\n'\nADMISSION_MARKER = '\\n## DSA — Docker startup exact source admission, 2026-11-08\\n\\n```json\\n'\nPURPOSE_MARKER = '\\n## Docker startup address-space comparison purpose 20261108\\n\\n```json\\n'\nPREDECESSOR = {\n    'admission': {'bytes':7720,'sha256':'da73ded89448edbcdb42d94304d311a1b478398751d83dd383faefc448f60067'},\n    'sourcePurpose': {'bytes':18999,'sha256':'7d86b90e6069dad7284b62a42eaf45281c764a4fb3060e1a0d0572c3957b0c3f'}}\nSOURCE_REVIEWER = '/root/release_review'\nSOURCE_AUTHOR = '/root/model_release'\nGOVERNANCE_REVIEWER = '/root/language_release'\nGOVERNANCE_AUTHOR = '/root'\nBOUNDS = {'maximumTransportsPerCommand':1,'maximumSequentialChildren':2,'argv':['/usr/bin/docker','--version'],\n    'profiles':['INHERITED_AS','EXACT_AS_512_MIB'],'addressSpaceBytes':536870912,'commandSeconds':12,\n    'comparisonSeconds':15,'transportSeconds':45,'maximumStreamBytes':16384,'commandFreshSeconds':300,\n    'cpuSeconds':2,'coreBytes':0,'fileOutputBytes':0,'automaticReruns':0}\n\ndef require(value):\n    if not value:\n        raise ValueError('STARTUP_ADMISSION_REJECTED')\n\ndef unique(pairs):\n    value = {}\n    for key, item in pairs:\n        require(key not in value)\n        value[key] = item\n    return value\n\ndef decode(raw):\n    return json.loads(raw, object_pairs_hook=unique)\n\ndef canonical(value):\n    return json.dumps(value, sort_keys=True, separators=(',', ':'), allow_nan=False)\n\ndef read(path, cap):\n    fd = os.open(path, os.O_RDONLY | os.O_NOFOLLOW | os.O_CLOEXEC)\n    try:\n        info = os.fstat(fd)\n        require(stat.S_ISREG(info.st_mode) and 0 <= info.st_size <= cap)\n        with os.fdopen(fd, 'rb', closefd=False) as handle:\n            raw = handle.read(cap+1)\n        after = os.fstat(fd)\n        require(len(raw) == info.st_size and (info.st_ino,info.st_size,info.st_mtime_ns,info.st_ctime_ns) ==\n                (after.st_ino,after.st_size,after.st_mtime_ns,after.st_ctime_ns))\n        return raw\n    finally:\n        os.close(fd)\n\ndef pin(path, raw):\n    return {'path':path,'mode':'100644','bytes':len(raw),'blob':hashlib.sha1(b'blob '+str(len(raw)).encode()+b'\\0'+raw).hexdigest(),\n            'sha256':hashlib.sha256(raw).hexdigest()}\n\ndef wire(value):\n    return json.dumps(value, ensure_ascii=False, separators=(',', ':'), allow_nan=False)\n\ndef record_block(text, marker, cap):\n    require(text.count(marker) == 1)\n    part = text.split(marker,1)[1].split('\\n```\\n',1)\n    require(len(part) == 2)\n    raw = part[0].encode('utf-8')\n    require(0 < len(raw) <= cap)\n    value = decode(raw)\n    require(type(value) is dict and wire(value).encode() == raw)\n    return value, raw\n\ndef artifact(value, minimum=1, maximum=1048576):\n    require(type(value) is dict and set(value) == {'bytes','sha256'} and\n            type(value['bytes']) is int and minimum <= value['bytes'] <= maximum and\n            type(value['sha256']) is str and re.fullmatch('[0-9a-f]{64}',value['sha256']))\n\ndef review_receipt(r, source):\n    keys = {'status','reviewerIdentity','authorIdentity','independent','findings','artifact','comment'}\n    require(type(r) is dict and set(r) == keys | ({'kind'} if source else set()))\n    require(r['status'] == 'CLEAN_PRIVATE_SOURCE_ONLY' and r['independent'] is True and type(r['findings']) is dict and\n            set(r['findings']) == {'P0','P1','P2'} and all(type(n) is int and n == 0 for n in r['findings'].values()))\n    require((r['reviewerIdentity'],r['authorIdentity']) ==\n            ((SOURCE_REVIEWER,SOURCE_AUTHOR) if source else (GOVERNANCE_REVIEWER,GOVERNANCE_AUTHOR)))\n    if source:\n        require(r['kind'] == 'PRIVATE_SOURCE_REVIEW')\n    artifact(r['artifact'],100,20000)\n    receipt = r['comment']\n    require(type(receipt) is dict and set(receipt) == {'id','issue','publisher','appId','createdAt'})\n    require(type(receipt['id']) is str and re.fullmatch('[1-9][0-9]{0,19}',receipt['id']))\n    require(type(receipt['issue']) is int and receipt['issue'] == 5469 and receipt['publisher'] == 'pachaninm-lab')\n    require(type(receipt['appId']) is int and receipt['appId'] == 1144995)\n    require(type(receipt['createdAt']) is str and re.fullmatch(r'[0-9]{4}-[0-9]{2}-[0-9]{2}T[0-9]{2}:[0-9]{2}:[0-9]{2}Z',receipt['createdAt']))\n    dt.datetime.fromisoformat(receipt['createdAt'].replace('Z','+00:00'))\n\ndef purpose(queue, sources):\n    require(type(queue) is bytes and len(queue) <= 3145728 and type(sources) is dict and tuple(sources) == SOURCE_PATHS)\n    text = queue.decode('utf-8')\n    prior = {}\n    for name,marker in (('admission',ADMISSION_MARKER),('sourcePurpose',PURPOSE_MARKER)):\n        value,raw = record_block(text,marker,PREDECESSOR[name]['bytes'])\n        require(len(raw) == PREDECESSOR[name]['bytes'] and hashlib.sha256(raw).hexdigest() == PREDECESSOR[name]['sha256'])\n        prior[name] = value\n    old = prior['admission']['core']\n    source = prior['sourcePurpose']\n    require(canonical(old['sourcePurpose']) == canonical(PREDECESSOR['sourcePurpose']))\n    require(canonical(old['bounds']) == canonical(source['bounds']) == canonical(BOUNDS))\n    require(canonical([p['after'] for p in old['sourcePayloads']]) == canonical(source['sourcePins']))\n    require(source['command'] == COMMAND and source['runtimeAllowance'] == old['runtimeAllowance'] == 'NOT_ISSUED_BY_SOURCE' and\n            old['productionInvocationAuthorized'] is False and source['authorityGranted'] == 'SOURCE_PURPOSE_ONLY_SEPARATE_FINITE_OWNER_COMMAND_REQUIRED')\n    v,_ = record_block(text,MARKER,4096)\n    require(set(v) == {'schema','core','governanceAfter','governancePatch','governanceReview'} and v['schema'] == 'pc.docker-startup-source-admission.v2')\n    core = v['core']\n    require(type(core) is dict and set(core) == {'purposeId','authorityBaseExactMain','retainedSourceHead','predecessor',\n        'sourceAfter','sourcePatch','sourceReview','runtimeAllowance'})\n    require((core['purposeId'],core['authorityBaseExactMain'],core['retainedSourceHead'],core['runtimeAllowance']) ==\n        (PURPOSE,BASE,RETAINED,'NOT_ISSUED_BY_SOURCE'))\n    require(canonical(core['predecessor']) == canonical(PREDECESSOR))\n    require(all(type(sources[p]) is bytes and 0 < len(sources[p]) <= cap for p,cap in zip(SOURCE_PATHS,SOURCE_CAPS)))\n    require(canonical(core['sourceAfter']) == canonical([pin(p,sources[p]) for p in SOURCE_PATHS]))\n    artifact(core['sourcePatch'])\n    review_receipt(core['sourceReview'],True)\n    require(type(v['governanceAfter']) is list and len(v['governanceAfter']) == 3)\n    for after,before in zip(v['governanceAfter'],prior['admission']['governanceAfter']):\n        require(type(after) is dict and set(after) == {'path','mode','blob','bytes','sha256'})\n        require((after['path'],after['mode']) == (before['path'],before['mode']) and type(after['blob']) is str and\n                re.fullmatch('[0-9a-f]{40}',after['blob']) and after['blob'] != before['blob'])\n        artifact({k:after[k] for k in ('bytes','sha256')})\n    artifact(v['governancePatch'])\n    review_receipt(v['governanceReview'],False)\n    require(core['sourceReview']['comment']['id'] != v['governanceReview']['comment']['id'])\n    return v\n\ndef source_review(record, live):\n    r = record['core']['sourceReview']\n    review_receipt(r,True)\n    receipt = r['comment']\n    require(type(live) is dict and type(live['id']) is int and str(live['id']) == receipt['id'])\n    require(live['issue_url'] == 'https://api.github.com/repos/pachaninm-lab/pachanin-demo/issues/5469' and\n            live['user']['login'] == receipt['publisher'] and live['author_association'] == 'OWNER')\n    app = live['performed_via_github_app']['id']\n    require(type(app) is int and app == receipt['appId'])\n    require(live['created_at'] == live['updated_at'] == receipt['createdAt'] and type(live['body']) is str)\n    raw = live['body'].encode('utf-8')\n    require(100 <= len(raw) == r['artifact']['bytes'] <= 20000 and hashlib.sha256(raw).hexdigest() == r['artifact']['sha256'])\n\ndef sections(sources):\n    # Runtime callers supply only accepted_sources() bytes; no new file is opened here.\n    require(type(sources) is dict and tuple(sources) == SOURCE_PATHS)\n    raw = sources[WORKFLOW]\n    require(hashlib.sha256(raw[:PREFIX_BYTES]).hexdigest() == PREFIX_SHA)\n    require(hashlib.sha256(sources[TEST][:62220]).hexdigest() == TEST_SHA)\n    def extract(tag):\n        rows = re.findall(rb\"^          (?:cat > .*|python3 .*|python3 -) <<'\"+tag.encode()+rb\"'\\n(.*?)^          \"+tag.encode()+rb\"\\n\",raw,re.M|re.S)\n        require(len(rows) == 1)\n        return textwrap.dedent(rows[0].decode())\n    old = extract('PY_CLOSED_DOCKER_SIGNAL')\n    classes = [n for n in ast.parse(old).body if isinstance(n,ast.ClassDef) and n.name == 'OwnedChildLease']\n    require(len(classes) == 1)\n    remote = 'import ctypes, os, signal, subprocess, time\\n'+ast.get_source_segment(old,classes[0])+'\\n'+sources[HOST].decode('utf-8')\n    require(len(remote.encode()) <= 20000)\n    host = {'__name__':'startup_host_validator'}\n    exec(compile(remote,'<accepted-startup-payload>','exec'),host)\n    transport = {'__name__':'startup_exact_retained_transport'}\n    exec(compile(extract('PY_CLOSED_DOCKER_TRANSPORT'),'<unchanged-accepted-transport>','exec'),transport)\n    return raw, remote, host, transport\n\ndef git(*args):\n    result = subprocess.run(['git','--no-replace-objects',*args],stdin=subprocess.DEVNULL,\n        stdout=subprocess.PIPE,stderr=subprocess.DEVNULL,timeout=10,env={**os.environ,'GIT_NO_LAZY_FETCH':'1','GIT_OPTIONAL_LOCKS':'0'})\n    require(result.returncode == 0)\n    return result.stdout\n\ndef accepted_blob(target,path,cap):\n    fields = git('ls-tree',target,'--',path).decode().strip().split()\n    require(len(fields) == 4 and fields[:2] == ['100644','blob'] and fields[3] == path and re.fullmatch('[0-9a-f]{40}',fields[2]))\n    length = git('cat-file','-s',fields[2]).strip()\n    require(re.fullmatch(rb'[0-9]{1,8}',length) and int(length) <= cap)\n    raw = git('cat-file','blob',fields[2])\n    require(len(raw) == int(length) and pin(path,raw)['blob'] == fields[2] and read(path,cap) == raw)\n    require(not os.lstat(path).st_mode & 0o111)\n    return raw\n\ndef accepted_sources(target):\n    require(type(target) is str and re.fullmatch('[0-9a-f]{40}',target) and git('rev-parse','HEAD').decode().strip() == target)\n    sources = {p:accepted_blob(target,p,cap) for p,cap in zip(SOURCE_PATHS,SOURCE_CAPS)}\n    record = purpose(accepted_blob(target,QUEUE,3145728),sources)\n    git('merge-base','--is-ancestor',BASE,target)\n    git('merge-base','--is-ancestor',RETAINED,target)\n    return sources,record\n\nclass NoRedirect(urllib.request.HTTPRedirectHandler):\n    def redirect_request(self,*args,**kwargs):\n        return None\n\ndef api(path):\n    require(path in ('git/ref/heads/main','issues/4637') or re.fullmatch(r'issues/comments/[1-9][0-9]{0,19}',path))\n    request = urllib.request.Request('https://api.github.com/repos/pachaninm-lab/pachanin-demo/'+path,\n        headers={'Authorization':'Bearer '+os.environ['GH_TOKEN'],'Accept':'application/vnd.github+json','X-GitHub-Api-Version':'2022-11-28'})\n    with urllib.request.build_opener(NoRedirect).open(request,timeout=10) as response:\n        require(response.status == 200)\n        raw = response.read(65537)\n        require(len(raw) <= 65536)\n    return decode(raw)\n\ndef owner(event,live,now):\n    require(type(event) is dict and event.get('action') == 'created' and event['issue']['number'] == 4637 and 'pull_request' not in event['issue'])\n    prior = event['comment']\n    require(type(prior['id']) is int and prior['id'] > 0 and type(live['id']) is int and live['id'] == prior['id'])\n    require(live['issue_url'] == 'https://api.github.com/repos/pachaninm-lab/pachanin-demo/issues/4637')\n    require(prior['body'] == live['body'] == COMMAND and live['user']['login'] == prior['user']['login'] == 'pachaninm-lab')\n    require(live['author_association'] == prior['author_association'] == 'OWNER')\n    require(live['created_at'] == live['updated_at'] == prior['created_at'] == prior['updated_at'])\n    require(re.fullmatch(r'[0-9]{4}-[0-9]{2}-[0-9]{2}T[0-9]{2}:[0-9]{2}:[0-9]{2}Z',live['created_at']))\n    stamp = dt.datetime.fromisoformat(live['created_at'].replace('Z','+00:00'))\n    require(0 <= (now-stamp).total_seconds() <= 255)\n    direct = os.environ['GITHUB_ACTOR'] == os.environ['TRIGGERING_ACTOR'] == 'pachaninm-lab'\n    app = (live.get('performed_via_github_app') or {}).get('id')\n    prior_app = (prior.get('performed_via_github_app') or {}).get('id')\n    require(direct or type(app) is int and type(prior_app) is int and app == prior_app == 1144995)\n    return str(prior['id'])\n\ndef admit():\n    require(os.environ['GITHUB_REPOSITORY'] == 'pachaninm-lab/pachanin-demo' and\n            os.environ['GITHUB_EVENT_NAME'] == 'issue_comment' and os.environ['GITHUB_RUN_ATTEMPT'] == '1' and\n            os.environ['GITHUB_REF'] == 'refs/heads/main')\n    target = os.environ['GITHUB_SHA']\n    require(re.fullmatch('[0-9a-f]{40}',target) and target == os.environ['GITHUB_WORKFLOW_SHA'] == git('rev-parse','HEAD').decode().strip())\n    require(os.environ['GITHUB_WORKFLOW_REF'] == 'pachaninm-lab/pachanin-demo/'+WORKFLOW+'@refs/heads/main')\n    sources,record = accepted_sources(target)\n    prepared = sections(sources)\n    event = decode(read(os.environ['GITHUB_EVENT_PATH'],1048576))\n    identifier = event['comment']['id']\n    require(type(identifier) is int and 0 < identifier < 10**20)\n    owner(event,api('issues/comments/'+str(identifier)),dt.datetime.now(dt.timezone.utc))\n    source_review(record,api('issues/comments/'+record['core']['sourceReview']['comment']['id']))\n    issue = api('issues/4637')\n    require(issue['state'] == 'open' and 'pull_request' not in issue and type(issue['comments']) is int and 0 <= issue['comments'] < 2500)\n    ref = api('git/ref/heads/main')\n    require(ref['ref'] == 'refs/heads/main' and ref['object']['type'] == 'commit' and ref['object']['sha'] == target)\n    # Freshness is checked again after all network/source work, before any protected transport.\n    owner(event,api('issues/comments/'+str(identifier)),dt.datetime.now(dt.timezone.utc))\n    return target,prepared\n\ndef publish(target,path,host):\n    v = decode(read(path,4096))\n    require(type(v) is dict and set(v) == {'schema','target','transport_status','diagnostic','passed',\n        'production_mutation','deployment_authorized','local_cleanup_attestation'})\n    require(v['schema'] == 'pc.closed-docker-diagnostic-envelope.v2' and v['target'] == target and\n        v['production_mutation'] is False and v['deployment_authorized'] is False and type(v['passed']) is bool)\n    require(v['local_cleanup_attestation'] in {'NOT_STARTED','OWNED_ANCESTRY_REAPED','NOT_ATTESTED'})\n    require(v['transport_status'] in {'UNKNOWN','TIMED_OUT','OUTPUT_LIMIT','NONZERO','INVALID_REMOTE_REPORT','CLEANUP_UNCONFIRMED','VALIDATED_REMOTE_REPORT'})\n    require((v['transport_status'] == 'CLEANUP_UNCONFIRMED') == (v['local_cleanup_attestation'] == 'NOT_ATTESTED'))\n    if v['transport_status'] == 'VALIDATED_REMOTE_REPORT':\n        report = host['validate_report'](v['diagnostic'])\n        require(v['local_cleanup_attestation'] == 'OWNED_ANCESTRY_REAPED' and v['passed'] == (report['status'] == 'SUCCESS'))\n    else:\n        require(v['diagnostic'] is None and not v['passed'])\n    return v\n\ndef main(mode):\n    require(mode in {'--admit','--key-script','--run','--publish'})\n    if mode in {'--admit','--run'}:\n        target,prepared = admit()\n    else:\n        target = os.environ['GITHUB_SHA']\n        sources,_ = accepted_sources(target)\n        prepared = sections(sources)\n    workflow,remote,host,transport = prepared\n    if mode == '--key-script':\n        job = workflow.decode().split('\\n  diagnose:\\n',1)[1].split('\\n\\n  inspect:\\n',1)[0]\n        block = job.split('      - name: Resolve protected key and pinned VPS identity\\n',1)[1].split('      - name:',1)[0]\n        print(textwrap.dedent(block.split('        run: |\\n',1)[1]),end='')\n        return 0\n    if mode == '--admit':\n        return 0\n    path = Path(os.environ['RUNNER_TEMP'])/'docker-startup-candidate.json'\n    if mode == '--run':\n        v = transport['execute'](remote,target,path)\n        return 0 if v['passed'] else 1\n    require(mode == '--publish' and re.fullmatch('[0-9a-f]{40}',target))\n    v = publish(target,path,host)\n    out = Path('artifacts/docker-startup-address-space')\n    out.mkdir(parents=True,exist_ok=True)\n    (out/'closed-result.json').write_text(json.dumps(v,sort_keys=True,separators=(',',':'))+'\\n')\n    diagnostic = v['diagnostic']\n    result = diagnostic['comparison'] if diagnostic is not None else 'NOT_PROVEN'\n    with open(os.environ['GITHUB_STEP_SUMMARY'],'a') as handle:\n        handle.write('## Daemon-free Docker startup comparison\\n\\nExact source: `'+target+'`. Result: `'+result+'`.\\n\\n'+\n            'Only fixed --version startup was measured. Production Docker daemon/original19/root cause/DB/restore/API delivery remain NOT_ATTESTED or NOT_ESTABLISHED. No automatic retry or release authorization.\\n')\n    return 0\n\nif __name__ == '__main__':\n    try:\n        require(len(sys.argv) == 2)\n        raise SystemExit(main(sys.argv[1]))\n    except Exception:\n        print('STARTUP_DIAGNOSTIC_NOT_PROVEN; NO_RETRY_OR_RELEASE_AUTHORITY',file=sys.stderr)\n        raise SystemExit(1) from None\n"}];
