test('DSA3: actual old-step condition accepts only completed positive new coverage',()=>{
  const block=workflow.split('      - name: Validate recovered plaintext Docker source at exact accepted head\n')[1];
  const expression=block.match(/        if: ([^\n]+)/u)[1];
  // GitHub string equality is case-insensitive, unlike JavaScript equality.
  // Evaluate the actual condition with that documented comparison semantics.
  // The native writer is independently required to emit exact lowercase bytes.
  const translated=expression.replace(/([A-Za-z_][A-Za-z0-9_.]*) == '([^']*)'/gu,(_,operand,literal)=>
    'ghaEqual('+operand+','+JSON.stringify(literal)+')');
  assert.equal((translated.match(/ghaEqual\(/gu)||[]).length,(expression.match(/ == /gu)||[]).length);
  assert.ok(!translated.includes(' == '));
  const number=value=>{
    if(value===null||value===undefined)return 0;
    if(typeof value==='boolean')return value?1:0;
    if(typeof value==='number')return value;
    if(typeof value!=='string')return NaN;
    if(value==='')return 0;
    try{const parsed=JSON.parse(value);return typeof parsed==='number'?parsed:NaN;}catch{return NaN;}
  };
  const ghaEqual=(a,b)=>typeof a==='string'&&typeof b==='string'?a.toLowerCase()===b.toLowerCase():
    typeof a===typeof b?a===b:number(a)===number(b);
  const evaluate=(outcome,accepted,prior=true,event='pull_request',branch=coDB)=>runInNewContext('('+translated+')',{
    github:{event_name:event,head_ref:branch},success:()=>prior,
    steps:{dsa3_source_controls:{outcome,outputs:{accepted}}},ghaEqual,
  });
  assert.equal(evaluate('success','true'),false);
  assert.equal(evaluate('success','TRUE'),false);
  assert.equal(evaluate('SUCCESS','True'),false);
  for(const [outcome,accepted] of [['success','false'],['skipped',undefined],['failure','true'],[undefined,undefined],
    ['success',true],['success','true\n'],['success',undefined]])assert.equal(evaluate(outcome,accepted),true);
  for(const [outcome,accepted] of [['success','true'],['success','false'],['failure','true']])assert.equal(evaluate(outcome,accepted,false),false);
  assert.equal(evaluate('success','false',true,'push'),false);
  assert.equal(evaluate('success','false',true,'pull_request','other-owner'),false);
});

test('DSA3: real Git admission, unchanged scopes and exact native snapshot',async t=>{
  const root=fs.mkdtempSync(path.join(os.tmpdir(),'dsa3-real-git-'));
  t.after(()=>fs.rmSync(root,{recursive:true,force:true,maxRetries:10,retryDelay:100}));
  const g=(...args)=>coGit(root,args);
  g('init','--initial-branch=main');
  for(const [key,value] of [['user.name','SYNTHETIC DSA3 fixtures'],['user.email','dsa3@example.invalid'],
    ['gc.auto','0'],['maintenance.auto','false']])g('config',key,value);
  write(root,'.git/objects/info/alternates',coObjectDirectory+'\n');
  const shallow=coRepoGit('rev-parse','--git-path','shallow').toString().trim();
  if(fs.existsSync(shallow))write(root,'.git/shallow',fs.readFileSync(shallow));
  const put=(file,bytes,mode='100644')=>{
    if(bytes===null){g('update-index','--force-remove',file);return;}
    const blob=coGit(root,['hash-object','-w','--stdin'],{input:bytes}).toString().trim();
    g('update-index','--add','--cacheinfo',mode,blob,file);
  };
  const commit=(from,edits=[],parents=[from])=>{
    g('read-tree',from);
    for(const [file,bytes,mode] of edits)put(file,bytes,mode);
    // Local partial object stores may omit unrelated, unchanged leaf contents.
    // Complete tree IDs and every read/executed blob remain exact and checked.
    return g('commit-tree',g('write-tree','--missing-ok').toString().trim(),...parents.flatMap(p=>['-p',p]),
      '-m','SYNTHETIC DSA3 local fixture; no public/source/host acceptance').toString().trim();
  };
  const pin=(file,bytes,mode='100644')=>({path:file,mode,blob:coBlob(bytes),bytes:bytes.length,sha256:coSha(bytes)});
  const origin=dsa3Core.authorityBaseExactMain,retained=dsa3Core.retainedSourceHead;
  const originalQueue=g('show',origin+':'+coQueue);
  const originalReview=g('show',origin+':'+dsa3ReviewPath);
  const sourceFiles=dsa3Core.sourceAfter.map((p,i)=>{
    const bytes=dsa3SourceBytes(i,g);
    assert.deepEqual(pin(p.path,bytes),p);return [p.path,bytes,p.mode];
  });
  const governancePaths=['.github/workflows/platform-v7-autopilot-guard.yml',
    'docs/platform-v7/autopilot/gekta-recovery-scope.test.mjs','scripts/p7-autopilot-guard.sh'];
  const governance=governancePaths.map(file=>[file,fs.readFileSync(file),file.endsWith('.sh')?'100755':'100644']);
  const governanceAfter=governance.map(([file,bytes,mode])=>pin(file,bytes,mode));
  // Only the following governance receipt is synthetic test data. Actual metadata
  // requires the complete genuine separately published review, not this fixture.
  const governanceReview={status:'CLEAN_PRIVATE_SOURCE_ONLY',reviewerIdentity:'/root/language_release',authorIdentity:'/root',
    independent:true,findings:{P0:0,P1:0,P2:0},artifact:{bytes:123,sha256:'c'.repeat(64)},
    comment:{id:'92',issue:5469,publisher:'pachaninm-lab',appId:1144995,createdAt:'2026-11-09T00:00:00Z'}};
  const admission={schema:'pc.docker-startup-source-admission.v3',core:dsa3Core,governanceAfter,
    governancePatch:{bytes:123,sha256:'b'.repeat(64)},governanceReview};
  const completeReview=(v=admission)=>Buffer.concat([originalReview,Buffer.from(dsa3Marker+JSON.stringify(v)+'\n```\n')]);
  const review=completeReview();assert.ok(review.length<=2097152);
  const queue=originalQueue;
  const metadata=commit(origin,[[dsa3ReviewPath,review]]);
  const base=commit(metadata,governance);
  const source=commit(base,sourceFiles,[retained,base]);
  const context=(head=source,accepted=base,branch=coDB)=>({root,head,base:accepted,branch});
  const body=sourceGuard.slice(sourceGuard.indexOf(dsa3GuardBegin),sourceGuard.indexOf(dsa3GuardEnd)+dsa3GuardEnd.length);
  const stage=(head=source,accepted=base,branchName=coDB)=>runInNewContext(body+'\ndsa3SourceStage();',{
    branch:branchName,baseRef:accepted,stateFile:statePath,Buffer,process:{env:{...process.env,HEAD_REF:head}},
    require:name=>{
      if(name==='node:crypto')return {createHash};
      if(name==='node:util')return {isDeepStrictEqual:dsaIsDeepStrictEqual};
      throw new Error('UNEXPECTED_DEPENDENCY');
    },execFileSync:(command,args,options)=>execFileSync(command,args,{...options,cwd:root}),
  },{timeout:20000});
  const retainedPaths=dsaCore.unchangedHelpers.filter(p=>!dsa3Core.sourceAfter.some(s=>s.path===p.path)).map(p=>p.path);
  const checkoutPaths=[...new Set([...retainedPaths,...sourceFiles.map(v=>v[0]),...governancePaths,
    coQueue,dsa3ReviewPath,statePath,'scripts/p7-source-controlled-scope.mjs','docs/platform-v7/autopilot/scopes/'])];
  g('config','core.sparseCheckout','true');
  write(root,'.git/info/sparse-checkout',checkoutPaths.map(p=>'/'+p).join('\n')+'\n');
  const checkout=head=>g('checkout','--force','--detach',head);
  checkout(source);
  await t.test('separate metadata then governance then retained-source transition passes',()=>{
    const actual=stage();assert.equal(actual.stage,'DSA3-SOURCE');assert.equal(actual.metadata,false);
    assert.deepEqual(Array.from(actual.scopes),dsa3Core.sourceAfter.map(p=>p.path));
    const result=coCheck(context());assert.equal(result.status,0,result.stdout+result.stderr);
  });
  await t.test('absent marker and other branch do not create new authority',()=>{
    assert.equal(stage(source,origin),undefined);assert.equal(stage(source,base,'other-owner'),undefined);
    const head=commit(origin,[[dsa3ReviewPath,review],...sourceFiles],[retained,origin]);
    const result=coCheck(context(head,origin));assert.notEqual(result.status,0);
  });
  await t.test('accepted old guard routes review-only metadata and exact governance without self-installation',()=>{
    for(const [head,accepted,branch] of [[metadata,origin,'governance/industrial-load-diagnostics-20260919'],
      [base,metadata,'governance/gekta-recovery-trusted-routes-20260927']]) {
      checkout(head);const result=coCheck(context(head,accepted,branch));assert.equal(result.status,0,result.stdout+result.stderr);
    }
    const foreign=commit(base,[['README.md',Buffer.from('foreign')]]);
    const result=coCheck(context(foreign,metadata,'governance/gekta-recovery-trusted-routes-20260927'));
    assert.notEqual(result.status,0);
    checkout(source);
  });
  const badRecord=change=>{
    const value=structuredClone(admission);change(value);
    const m=commit(origin,[[dsa3ReviewPath,completeReview(value)]]),b=commit(m,governance);
    return [commit(b,sourceFiles,[retained,b]),b];
  };
  for(const [name,change] of [
    ['unknown outer key',v=>{v.extra=true;}],['core drift',v=>{v.core.sourceAfter[0].bytes++;}],
    ['reordered core wire',v=>{v.core=Object.fromEntries(Object.entries(v.core).reverse());}],
    ['runtime allowance',v=>{v.core.runtimeAllowance='GRANTED';}],
    ['wrong governance hash',v=>{v.governanceAfter[0].sha256='d'.repeat(64);}],
    ['wrong governance mode',v=>{v.governanceAfter[0].mode='100755';}],
    ['missing governance pin',v=>{v.governanceAfter.pop();}],
    ['PENDING governance review',v=>{v.governanceReview.status='PENDING';}],
    ['historical generic CLEAN',v=>{v.governanceReview.status='CLEAN';}],
    ['self review',v=>{v.governanceReview.reviewerIdentity='/root';}],
    ['wrong source reviewer',v=>{v.core.sourceReview.reviewerIdentity='/root';}],
    ['boolean findings',v=>{v.governanceReview.findings.P0=false;}],
    ['missing review body',v=>{v.governanceReview.artifact.bytes=0;}],
    ['oversized review body',v=>{v.governanceReview.artifact.bytes=20001;}],
    ['numeric comment identifier',v=>{v.governanceReview.comment.id=92;}],
    ['leading-zero identifier',v=>{v.governanceReview.comment.id='092';}],
    ['wrong review issue',v=>{v.governanceReview.comment.issue=4637;}],
    ['string app identifier',v=>{v.governanceReview.comment.appId='1144995';}],
    ['invalid calendar date',v=>{v.governanceReview.comment.createdAt='2026-02-30T00:00:00Z';}],
    ['same review receipt',v=>{v.governanceReview.comment.id=v.core.sourceReview.comment.id;}],
    ['unknown review field',v=>{v.governanceReview.unapproved=true;}],
    ['empty patch',v=>{v.governancePatch.bytes=0;}],
    ['reused historical governance review id',v=>{v.governanceReview.comment.id='6735646734';}],
    ['reused historical governance review bytes',v=>{v.governanceReview.artifact.sha256='102aa5d4e4bbccb8bf3bad4f7541f645caf24af9dfa4d7965d7a0c24e25e9008';}],
  ])await t.test('rejects accepted-data '+name,()=>assert.throws(()=>stage(...badRecord(change)),/DSA3_SOURCE_SCOPE_/u));
  for(const [name,changed] of [
    ['duplicate marker',Buffer.concat([review,Buffer.from(dsa3Marker+'{}\n```\n')])],
    ['duplicate JSON key',Buffer.from(review.toString().replace('"schema":"pc.docker-startup-source-admission.v3"','"schema":"DUPLICATE","schema":"pc.docker-startup-source-admission.v3"'))],
    ['noncanonical record',Buffer.from(review.toString().replace(JSON.stringify(admission),' '+JSON.stringify(admission)))],
    ['malformed JSON',Buffer.from(review.toString().replace(JSON.stringify(admission),'{broken'))],
    ['review overflow',Buffer.concat([review,Buffer.alloc(2097152)])],
  ])await t.test('rejects '+name,()=>{
    const b=commit(base,[[dsa3ReviewPath,changed]]),h=commit(b,sourceFiles,[retained,b]);assert.throws(()=>stage(h,b),/DSA3_SOURCE_SCOPE_/u);
  });
  for(const [name,changed] of [
    ['queue epoch drift',Buffer.concat([queue,Buffer.from('\nextra')])],
    ['DSA2 predecessor drift',Buffer.from(queue.toString().replace('docker-startup-plaintext-recovery-20261109','docker-startup-plaintext-recovery-20261110'))],
  ])await t.test('rejects accepted '+name,()=>{
    const b=commit(base,[[coQueue,changed]]),h=commit(b,sourceFiles,[retained,b]);assert.throws(()=>stage(h,b),/DSA3_SOURCE_SCOPE_/u);
  });
  for(const [name,file,bytes,mode] of [
    ['extra path','README.md',Buffer.from('foreign')],['state drift',statePath,Buffer.from('{}')],
    ['queue drift',coQueue,Buffer.concat([queue,Buffer.from('\nextra')])],
    ['review drift',dsa3ReviewPath,Buffer.concat([review,Buffer.from('\nextra')])],
    ['workflow prefix drift',sourceFiles[0][0],Buffer.from('X'+sourceFiles[0][1].toString().slice(1))],
    ['old test drift',sourceFiles[1][0],Buffer.from('changed old test')],
    ['wrong helper bytes',sourceFiles[2][0],Buffer.from('wrong helper')],
    ['executable controller',sourceFiles[3][0],sourceFiles[3][1],'100755'],
    ['symlink controller',sourceFiles[3][0],Buffer.from('../README.md'),'120000'],
    ['deleted host',sourceFiles[2][0],null],['governance drift',governancePaths[0],Buffer.from('wrong governance')],
  ])await t.test('rejects candidate '+name,()=>{const h=commit(source,[[file,bytes,mode]]);assert.throws(()=>stage(h));});
  await t.test('requires retained source ancestry separately from accepted BASE ancestry',()=>{
    assert.throws(()=>stage(commit(base,sourceFiles,[base])));
    assert.throws(()=>stage(commit(base,sourceFiles,[retained])));
  });
  await t.test('added helper cannot already exist in accepted BASE',()=>{
    const b=commit(base,[sourceFiles[2]]),h=commit(b,sourceFiles,[retained,b]);assert.throws(()=>stage(h,b),/DSA3_SOURCE_SCOPE_ADDED_PATH_EXISTS/u);
  });
  const python=execFileSync('python3',['-c','import sys;print(sys.executable)'],{encoding:'utf8'}).trim();
  const native=workflow.split("          python3 -I -B - <<'DSA3_SOURCE_CONTROLS'\n")[1]
    .split('          DSA3_SOURCE_CONTROLS\n')[0].split('\n').map(l=>l.startsWith('          ')?l.slice(10):l).join('\n');
  const shared='scripts/test_production_stopped_runtime_headroom.py';
  const run=(candidate=source,accepted=base,{prepare=()=>{},helperFailure=false,extra=false}={})=>{
    checkout(candidate);
    const shim=path.join(root,'.git','dsa3-shim'),calls=path.join(root,'.git','dsa3-calls'),output=path.join(root,'.git','dsa3-output');
    fs.mkdirSync(shim,{recursive:true});fs.rmSync(calls,{force:true});fs.writeFileSync(output,'');
    write(root,'.git/dsa3-shim/python3','#!'+process.execPath+'\n'+
      "const fs=require('node:fs'),cp=require('node:child_process'),args=process.argv.slice(2);\n"+
      'if(args.includes('+JSON.stringify(shared)+')){fs.appendFileSync('+JSON.stringify(calls)+',"helper\\n");'+
      (helperFailure?'process.exit(7);':'')+(extra?'fs.writeFileSync("unapproved-extra","owned fixture");':'')+'}\n'+
      'const r=cp.spawnSync('+JSON.stringify(python)+',args,{stdio:"inherit",env:process.env});process.exit(r.status??1);\n');
    fs.chmodSync(path.join(shim,'python3'),0o700);prepare();
    const result=spawnSync(python,['-I','-B','-'],{cwd:root,input:native,encoding:'utf8',timeout:90000,maxBuffer:1048576,
      env:{...process.env,PATH:shim+path.delimiter+process.env.PATH,BASE_SHA:accepted,HEAD_SHA:candidate,
        GITHUB_HEAD_REF:coDB,GITHUB_OUTPUT:output,PYTHONDONTWRITEBYTECODE:'1'}});
    const line=result.stdout?.split('\n').find(v=>v.startsWith('DSA3_SOURCE_CONTROLS_PINNED_SNAPSHOT='));
    const snapshot=line?JSON.parse(line.slice('DSA3_SOURCE_CONTROLS_PINNED_SNAPSHOT='.length)):null;
    if(snapshot)assert.equal(fs.existsSync(snapshot.cwd),false,'owned snapshot removed on success and failure');
    return {result,snapshot,output:fs.readFileSync(output,'utf8'),calls:fs.existsSync(calls)?fs.readFileSync(calls,'utf8').trim().split('\n').length:0};
  };
  await t.test('native executes complete shared50 and startup suite in exact10+2 snapshot',()=>{
    const {result,snapshot,output,calls}=run();assert.equal(result.status,0,result.stdout+result.stderr);assert.equal(calls,1);
    assert.match(result.stderr,/Ran 50 tests[\s\S]*\bOK\b/u);assert.match(result.stderr,new RegExp('Ran '+dsa3StartupCount+' tests[\\s\\S]*\\bOK\\b','u'));
    assert.equal(snapshot.files.length,10);assert.deepEqual(snapshot.authorities.map(v=>[v.path,v.bytes]),[[coQueue,queue.length],[dsa3ReviewPath,review.length]]);
    assert.deepEqual(snapshot.files.map(v=>v.path),[...retainedPaths,...sourceFiles.map(v=>v[0])].sort());
    assert.equal(snapshot.head,source);assert.equal(output,'accepted=true\n');
    assert.match(result.stdout,/DSA3_SOURCE_CONTROLS_EXACT_HEAD_PASS; SHARED_UNFILTERED_AND_STARTUP_CONTRACT; SNAPSHOT_REMOVED; HOST_AUTHORITY=NONE/u);
  });
  await t.test('historical BASE emits false and executes no new helper',()=>{
    const {result,output,calls,snapshot}=run(retained,origin);assert.equal(result.status,0,result.stdout+result.stderr);
    assert.equal(output,'accepted=false\n');assert.equal(calls,0);assert.equal(snapshot,null);
  });
  for(const [name,options] of [['helper failure',{helperFailure:true}],['extra snapshot file',{extra:true}]])await t.test('native rejects '+name,()=>{
    const {result,output,calls,snapshot}=run(source,base,options);assert.notEqual(result.status,0);assert.equal(calls,1);
    assert.equal(snapshot.files.length,10);assert.equal(output,'');assert.doesNotMatch(result.stdout,/DSA3_SOURCE_CONTROLS_EXACT_HEAD_PASS/u);
  });
  for(const file of [...sourceFiles.map(v=>v[0]),coQueue,dsa3ReviewPath,governancePaths[0]])
    await t.test('native rejects dirty physical '+file,()=>{
      const {result,output,calls,snapshot}=run(source,base,{prepare:()=>fs.appendFileSync(path.join(root,file),'\n# dirty\n')});
      assert.notEqual(result.status,0);assert.equal(output,'');assert.equal(calls,0);assert.equal(snapshot,null);
    });
  await t.test('native refuses physical controller symlink before helper execution',()=>{
    const {result,output,calls}=run(source,base,{prepare:()=>{
      const saved=path.join(root,'.git','dsa3-controller-copy'),file=path.join(root,sourceFiles[3][0]);
      fs.copyFileSync(file,saved);fs.unlinkSync(file);fs.symlinkSync(saved,file);
    }});assert.notEqual(result.status,0);assert.equal(output,'');assert.equal(calls,0);
  });
});
